    public static class ExcelResult
    {
        private static void WriteToResponse(this byte[] outputFileBytes, string outputFileName)
        {
            HttpContext.Current.Response.ClearHeaders();
            HttpContext.Current.Response.ClearContent();
            HttpContext.Current.Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
            HttpContext.Current.Response.AddHeader("Content-Disposition", string.Format("attachment;filename={0}", outputFileName));
            HttpContext.Current.Response.BinaryWrite(outputFileBytes);
            HttpContext.Current.Response.Flush();
            HttpContext.Current.Response.End();
        }
        public static ActionResult AsExcelResult(this MemoryStream memoryStream, string caption)
        {
            //File name
            string fileName = String.Format("{0}.xlsx", caption);

            //https://en.wikipedia.org/wiki/Internet_media_type
            const string contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

            //Return ocet sream
            return new FileStreamResult(memoryStream, contentType)
            {
                FileDownloadName = fileName
            };

        }

        #region Streams

        public static MemoryStream AsExcelStream(this Report2SummaryExportModel model)
        {
            string sourcePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report2Summary.xlsx");
            byte[] data = File.ReadAllBytes(sourcePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);

            string title = string.Empty;

            if (model.FromMonth == model.ToMonth)
