            titleRow.Cell(2).Value = title;
            titleRow.Cell(2).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            titleRow.Cell(2).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            titleRow.Cell(2).Style.Alignment.WrapText = true;
            titleRow.Cell(2).Style.Font.Bold = true;

            #endregion

            #region Header

            int headerCellIndex = 2,
                headerRowIndex = 4;

            IXLRow headerFirstRow = ws.Row(headerRowIndex);
            IXLRow headerSecondRow = ws.Row(headerRowIndex + 1);
            IXLRow headerThirdRow = ws.Row(headerRowIndex + 2);

            #region Total

            ws.Range(headerRowIndex, headerCellIndex, headerRowIndex, headerCellIndex + 5).Merge();

            headerFirstRow.Cell(headerCellIndex).Value = "Жами".Localize();
