            headerThirdRow.Cell(headerCellIndex + 2).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            headerThirdRow.Cell(headerCellIndex + 2).Style.Alignment.WrapText = true;
            headerThirdRow.Cell(headerCellIndex + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
