                    headerThirdRow.Cell(headerCellIndex + 2).Style.Font.Bold = true;

                    headerCellIndex += 3;

                    if (index == 1)
                    {
                        ws.Range(headerRowIndex + 1, headerCellIndex, headerRowIndex + 1, headerCellIndex + 2).Merge();

                        headerSecondRow.Cell(headerCellIndex).Value = string.Format("{0} ({1})", "қиёсий нархларда".Localize(), subItem.Name);
