                contentRow.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                contentRow.Cell(contentCellIndex).Style.Alignment.WrapText = true;

                if (!item.PreviousYearValues.Any())
                    item.PreviousYearValues = item.CurrentYearValues.Select(s => new Report2SummaryExportModelItemValue()).ToList();

                #region Total
                var prevYearRealSum = item.PreviousYearValues.Sum(s => s.C_Real);
                contentRow.Cell(contentCellIndex + 1).Value = prevYearRealSum > 0 ? prevYearRealSum : null;
                contentRow.Cell(contentCellIndex + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
