                contentRow.Cell(contentCellIndex + 2).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                contentRow.Cell(contentCellIndex + 2).Style.Alignment.WrapText = true;

                var persentRealSum = prevYearRealSum > 0 ? (currYearRealSum > 0 ? currYearRealSum : 0) * 100 / prevYearRealSum : null;
