        public static MemoryStream AsExcelStream(this Report2RecordExportModel model)
        {
            string sourcePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report2Record.xlsx");
            byte[] data = File.ReadAllBytes(sourcePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(3);

            if (model.IsSummary)
            {
                string title = string.Empty;

                if (model.FromMonth == model.ToMonth)
                    title = string.Format("{0} бўйича {1} йил {2} ойида ишлаб чиқарилган саноат маҳсулотлари тўғрисида маълумот", model.OrganizationName, model.Year, model.FromMonth.AsEnumMember().Description);
                else
                    title = string.Format("{0} бўйича {1} йил {2} - {3} ойларида ишлаб чиқарилган саноат маҳсулотлари тўғрисида маълумот", model.OrganizationName, model.Year, model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);

                titleRow.Cell(2).Value = title;
            }
            else
                titleRow.Cell(2).Value = string.Format("{0} бўйича {1} йил {2} ойида ишлаб чиқарилган саноат маҳсулотлари тўғрисида маълумот", model.OrganizationName, model.Year, model.Month.AsEnumMember().Description);

            titleRow.Cell(2).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            titleRow.Cell(2).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            titleRow.Cell(2).Style.Alignment.WrapText = true;
            titleRow.Cell(2).Style.Font.Bold = true;

