        public static MemoryStream AsExcelStream(this Report7RecordViewModel model)
        {
            string sourcePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report7Record.xlsx");
            byte[] data = File.ReadAllBytes(sourcePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} ойида йўл ишлари дастурларига киритилган объектлардаги қуриш, қайта қуриш ва тўла таъмирлаш ишларининг олиб борилиши тўғрисида маълумот", model.OrganizationName, model.Year, model.Month.AsEnumMember().Description);

            #endregion

            #region Header

            IXLRow firstHeaderRow = ws.Row(5);

            firstHeaderRow.Cell(5).Value = string.Format("{0} йилдан ўтган", model.Year - 1);
            firstHeaderRow.Cell(7).Value = string.Format("{0} йил 1-январь ҳолатига жами ишлатилган битум маҳсулоти", model.Year, model.Month.AsEnumMember().Description);
            firstHeaderRow.Cell(9).Value = string.Format("{0} йил 1-январь ҳолатига жами ишлатилган асфальтобетон маҳсулоти", model.Year, model.Month.AsEnumMember().Description);
            firstHeaderRow.Cell(10).Value = string.Format("{0} йилдан ўтган битум қолдиғи", model.Year - 1);
            firstHeaderRow.Cell(12).Value = string.Format("{0} йил шартномавий қиймати", model.Year);
            firstHeaderRow.Cell(18).Value = string.Format("{0} йил {1} ойида олинган битум", model.Year, model.Month.AsEnumMember().Description);
            firstHeaderRow.Cell(24).Value = string.Format("{0} йил {1} ойида амалда бажарилган ишлар.", model.Year, model.Month.AsEnumMember().Description);
            firstHeaderRow.Cell(26).Value = string.Format("{0} йил учун жами талаб этиладиган битум маҳсулоти", model.Year);

            IXLRow secondHeaderRow = ws.Row(6);

            secondHeaderRow.Cell(13).Value = string.Format("{0} йилда Молиялаштирилиши", model.Year);

            #endregion

            #region Content

            int contentRowIndex = 8,
                contentCellIndex = 1;
            var _rows = IoCHelper.GetInstance<Report7RowService>().AllAsQueryable;
            var values = model.Values.GroupBy(g => g.RowId);

            foreach (var item in values)
            {
