        public static MemoryStream AsExcelStream(this Report7SummaryExportModel model)
        {
            string sourcePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report7Summary.xlsx");
            byte[] data = File.ReadAllBytes(sourcePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");
            ws.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;

            #region Title

            IXLRow titleRow = ws.Row(2);

            string title = string.Empty;

            if (model.FromMonth == model.ToMonth)
                title = string.Format("{0} бўйича {1} йил {2} ойида йўл ишлари дастурларига киритилган объектлардаги қуриш, қайта қуриш ва тўла таъмирлаш ишларининг олиб борилиши тўғрисида маълумот", model.OrganizationName, model.Year, model.FromMonth.AsEnumMember().Description);
            else
                title = string.Format("{0} бўйича {1} йил {2} - {3} ойларида йўл ишлари дастурларига киритилган объектлардаги қуриш, қайта қуриш ва тўла таъмирлаш ишларининг олиб борилиши тўғрисида маълумот", model.OrganizationName, model.Year, model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);

            titleRow.Cell(1).Value = title;

            #endregion

            #region Header

            IXLRow firstHeaderRow = ws.Row(5);

            firstHeaderRow.Cell(6).Value = string.Format("{0} йилдан ўтган", model.Year - 1);
            firstHeaderRow.Cell(8).Value = string.Format("{0} йил 1-январь ҳолатига жами ишлатилган битум маҳсулоти", model.Year);
            firstHeaderRow.Cell(10).Value = string.Format("{0} йил 1-январь ҳолатига жами ишлатилган асфальтобетон маҳсулоти", model.Year);
            firstHeaderRow.Cell(11).Value = string.Format("{0} йилдан ўтган битум қолдиғи", model.Year - 1);
            firstHeaderRow.Cell(13).Value = string.Format("{0} йил шартномавий қиймати", model.Year);
