        public static MemoryStream AsExcelStream(this Report9SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report9Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(3);

            titleRow.Cell(1).Value = model.ProtocolName;
            titleRow.Cell(1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            titleRow.Cell(1).Style.Alignment.WrapText = true;
            titleRow.Cell(1).Style.Font.Bold = true;
            titleRow.Cell(1).Style.Font.FontSize = 16;

            IXLRow dateRow = ws.Row(7);

            dateRow.Cell(1).Value = string.Format("{0} - {1} йиллар оралиғи ҳолатига", model.FromDate.ToShortDateString(), model.ToDate.ToShortDateString());
            dateRow.Cell(1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;

            #endregion

            #region Content

            int contentRowIndex = 10,
                contentCellIndex = 1;

            foreach (var item in model.Items)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                ws.Range(contentRowIndex, contentCellIndex, contentRowIndex++, contentCellIndex + 4).Merge();

                contentRowFirst.Cell(contentCellIndex).Value = string.Format("    {0}", item.ChildOrganizationName);
                contentRowFirst.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                contentRowFirst.Cell(contentCellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowFirst.Cell(contentCellIndex).Style.Font.Bold = true;

                contentRowFirst.Cell(contentCellIndex + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowFirst.Cell(contentCellIndex + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowFirst.Cell(contentCellIndex + 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowFirst.Cell(contentCellIndex + 4).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);


                foreach (var value in item.Values)
                {
                    IXLRow contentRowSecond = ws.Row(contentRowIndex);

                    ws.Range(contentRowIndex, contentCellIndex, contentRowIndex++, contentCellIndex + 4).Merge();

                    contentRowSecond.Cell(contentCellIndex).Value = string.Format("                              {0} йил ҳолатига", value.ReportDate.ToShortDateString());
                    contentRowSecond.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                    contentRowSecond.Cell(contentCellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowSecond.Cell(contentCellIndex).Style.Fill.BackgroundColor = XLColor.FromHtml("#C8C7C8");
                    contentRowSecond.Cell(contentCellIndex).Style.Font.Underline = XLFontUnderlineValues.Single;
                    contentRowSecond.Cell(contentCellIndex).Style.Font.Italic = true;

                    contentRowSecond.Cell(contentCellIndex + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowSecond.Cell(contentCellIndex + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowSecond.Cell(contentCellIndex + 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowSecond.Cell(contentCellIndex + 4).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);


                    int i = 1;
                    foreach (var subValue in value.SubValues)
                    {
                        IXLRow contentRowThird = ws.Row(contentRowIndex++);

                        contentRowThird.Cell(contentCellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

                        contentRowThird.Cell(contentCellIndex + 1).Value = i++;
                        contentRowThird.Cell(contentCellIndex + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

                        contentRowThird.Cell(contentCellIndex + 2).Value = subValue.Task;
                        contentRowThird.Cell(contentCellIndex + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowThird.Cell(contentCellIndex + 2).Style.Alignment.WrapText = true;

                        contentRowThird.Cell(contentCellIndex + 3).Value = subValue.State;
                        contentRowThird.Cell(contentCellIndex + 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowThird.Cell(contentCellIndex + 3).Style.Alignment.WrapText = true;

                        contentRowThird.Cell(contentCellIndex + 4).Value = subValue.Problem;
                        contentRowThird.Cell(contentCellIndex + 4).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowThird.Cell(contentCellIndex + 4).Style.Alignment.WrapText = true;
                    }

                }
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

