        public static MemoryStream AsExcelStream(this Report12RecordViewModel model)
        {
            string sourcePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), "Report12Record.xlsx");
            byte[] data = File.ReadAllBytes(sourcePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} ойида умумий фойдаланишдаги халқаро ва давлат аҳамиятидаги автомобиль йўлларини қуриш ва қайта қуриш дастурига киритлган объектларда амалга оширилган ва ушбу ишларни амалга оширишда юзага келаётган муаммолар тўғрисида маълумот", model.OrganizationName, model.Year, model.Month.AsEnumMember().Description);

            #endregion

            #region Content

            int contentRowIndex = 6,
                contentCellIndex = 1;
            var _rows = IoCHelper.GetInstance<Report12RowService>().AllAsQueryable;
            var values = model.Values.GroupBy(g => g.RowId);

            foreach (var item in values)
            {
                #region Total

                IXLRow contentTotalRow = ws.Row(contentRowIndex++);

                contentTotalRow.Cell(contentCellIndex).Value = _rows.FirstOrDefault(f => f.Id == item.Key).GetCurrentLocale().Name;
                contentTotalRow.Cell(contentCellIndex).Style.Font.Bold = true;
                contentTotalRow.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                contentTotalRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                for (int i = 0; i < 4; i++)
                {
                    contentTotalRow.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentTotalRow.Cell(contentCellIndex + i).Style.Fill.BackgroundColor = XLColor.FromHtml("#D2D6DE");
                }

                #endregion

                #region Column

                foreach (var subItem in item)
                {
                    IXLRow contentRow = ws.Row(contentRowIndex++);
                    contentRow.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRow.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;

                    contentRow.Cell(contentCellIndex).Value = subItem.ObjectName;
                    contentRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;

                    contentRow.Cell(contentCellIndex + 1).Value = subItem.Address;
                    contentRow.Cell(contentCellIndex + 2).Value = subItem.ExecutedWorks;
                    contentRow.Cell(contentCellIndex + 3).Value = subItem.Problems;

                    for (int k = 0; k < 4; k++)
                    {
                        contentRow.Cell(contentCellIndex + k).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRow.Cell(contentCellIndex + k).Style.Font.Bold = true;
                    }
                }

                #endregion
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

