                title = string.Format("{0} бўйича {1} йил {2} - {3} ойларида умумий фойдаланишдаги халқаро ва давлат аҳамиятидаги автомобиль йўлларини қуриш ва қайта қуриш дастурига киритлган объектларда амалга оширилган ва ушбу ишларни амалга оширишда юзага келаётган муаммолар тўғрисида маълумот", model.OrganizationName, model.Year, model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);

            titleRow.Cell(1).Value = title;

            #endregion

            #region Content

            int contentRowIndex = 6,
                contentCellIndex = 1;

            if (model.IsGeneral)
            {
                var values = model.Values.GroupBy(g => g.RegionId);

                foreach (var value in values)
                {
                    IXLRow headerRow = ws.Row(contentRowIndex++);
                    ws.Range(contentRowIndex - 1, contentCellIndex + 1, contentRowIndex - 1, contentCellIndex + 4).Merge();

                    headerRow.Cell(contentCellIndex).Value = value.FirstOrDefault().RegionName;
                    headerRow.Cell(contentCellIndex).Style.Font.Bold = true;

                    for (int i = 0; i < 5; i++)
                    {
                        headerRow.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        headerRow.Cell(contentCellIndex + i).Style.Fill.BackgroundColor = XLColor.FromHtml("#D2D6DE");
                    }

                    var grouppedRows = value.GroupBy(g => g.RowId);

                    foreach (var row in grouppedRows)
                    {
                        #region Total

                        IXLRow contentTotalRow = ws.Row(contentRowIndex++);
                        contentTotalRow.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        contentTotalRow.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;

                        for (int j = 0; j < 5; j++)
                            contentTotalRow.Cell(contentCellIndex + j).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

                        contentTotalRow.Cell(contentCellIndex).Value = row.FirstOrDefault().RowName;
                        contentTotalRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                        contentTotalRow.Cell(contentCellIndex).Style.Font.Bold = true;

                        #endregion

                        #region Column

                        foreach (var subItem in row)
                        {
                            IXLRow contentRow = ws.Row(contentRowIndex++);

                            for (int k = 0; k < 5; k++)
                            {
                                contentRow.Cell(contentCellIndex + k).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                                contentRow.Cell(contentCellIndex + k).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                                contentRow.Cell(contentCellIndex + k).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                                contentRow.Cell(contentCellIndex + k).Style.Alignment.WrapText = true;
                            }

                            contentRow.Cell(contentCellIndex).Value = subItem.ObjectName;
                            contentRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;

                            contentRow.Cell(contentCellIndex + 1).Value = subItem.OrganizationName;
                            contentRow.Cell(contentCellIndex + 2).Value = subItem.Address;
                            contentRow.Cell(contentCellIndex + 3).Value = subItem.ExecutedWorks;
                            contentRow.Cell(contentCellIndex + 4).Value = subItem.Problems;
                        }

                        #endregion
                    }
                }
            }
            else
            {
                var values = model.Values.GroupBy(g => g.RowId);

                foreach (var item in values)
                {
                    #region Total

                    IXLRow contentTotalRow = ws.Row(contentRowIndex++);

                    contentTotalRow.Cell(contentCellIndex).Value = item.FirstOrDefault().RowName;
                    contentTotalRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentTotalRow.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentTotalRow.Cell(contentCellIndex).Style.Font.Bold = true;

                    for (int i = 0; i < 5; i++)
                    {
                        contentTotalRow.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentTotalRow.Cell(contentCellIndex + i).Style.Fill.BackgroundColor = XLColor.FromHtml("#D2D6DE");
                    }

                    #endregion

                    #region Column

                    foreach (var subItem in item)
                    {
                        IXLRow contentRow = ws.Row(contentRowIndex++);
                        contentRow.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        contentRow.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;

                        contentRow.Cell(contentCellIndex).Value = subItem.ObjectName;
                        contentRow.Cell(contentCellIndex).Style.Alignment.WrapText = true;
                        contentRow.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;

                        contentRow.Cell(contentCellIndex + 1).Value = subItem.OrganizationName;
                        contentRow.Cell(contentCellIndex + 2).Value = subItem.Address;
                        contentRow.Cell(contentCellIndex + 3).Value = subItem.ExecutedWorks;
                        contentRow.Cell(contentCellIndex + 4).Value = subItem.Problems;

                        for (int k = 0; k < 5; k++)
                            contentRow.Cell(contentCellIndex + k).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    }

                    #endregion
                }
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

