                    IXLRow contentRowSecond = ws.Row(contentRowIndex++);

                    for (int i = 0; i < 5; i++)
                    {
                        contentRowSecond.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSecond.Cell(contentCellIndex + i).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        contentRowSecond.Cell(contentCellIndex + i).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
