                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(2).Value = string.Format("{0} бўйича {1} {2} йилда қора металл чиқиндилари топширилиши тўғрисидаги маълумот", model.OrganizationName, model.Month.AsEnumMember().Description, model.Year);

            #endregion

            #region Header

            IXLRow firstHeaderRow = ws.Row(6);

            firstHeaderRow.Cell(3).Value = string.Format("{0} - {1} ойлари режаси", model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);
            firstHeaderRow.Cell(4).Value = string.Format("{0} - {1} ойлари амалда", model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);
            firstHeaderRow.Cell(7).Value = string.Format("{0} ойи режаси", model.Month.AsEnumMember().Description);
            firstHeaderRow.Cell(8).Value = string.Format("{0} ойи амалда", model.Month.AsEnumMember().Description);

            #endregion

            #region Content

            var organization = IoCHelper.GetInstance<OrganizationService>().AllAsQueryable.Where(a => a.Id == model.OrganizationId).FirstOrDefault();

            int contentRowIndex = 9,
                contentCellIndex = 1;

            int index = 1;
            foreach (var item in organization.Children)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                //ws.Range(contentRowIndex, contentCellIndex + 1, contentRowIndex, contentCellIndex + 9).Merge();

                for (int i = 0; i < 10; i++)
                {
                    contentRowFirst.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowFirst.Cell(contentCellIndex + i).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRowFirst.Cell(contentCellIndex + i).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                }


                contentRowFirst.Cell(contentCellIndex).Value = index++;
                contentRowFirst.Cell(contentCellIndex + 1).Value = item.GetCurrentLocale().ShortName;
                var recordValues = model.RecordValues.FirstOrDefault(a => a.OrganizationId == item.Id);
                var planValues = model.PlanValues.Where(a => a.OrganizationId == item.Id).FirstOrDefault();

                var monthlyRecordValues = model.MonthlyRecordValues.FirstOrDefault(a => a.OrganizationId == item.Id);
                var monthlyPlanValues = model.MonthlyPlanValues.Where(a => a.OrganizationId == item.Id).FirstOrDefault();

                if (recordValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 3).Value = recordValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 4).Value = recordValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 5).Value = string.Format("{0:F2}", recordValues.C1 * 100 / planValues.C1);
                }
                if (planValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 2).Value = planValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 4).Value = 0 - planValues.C1;
                }
                if (recordValues != null && planValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 4).Value = recordValues.C1 - planValues.C1;
                }
                //////
                if (monthlyRecordValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 7).Value = monthlyRecordValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 8).Value = monthlyRecordValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 9).Value = string.Format("{0:F2}", monthlyRecordValues.C1 * 100 / monthlyPlanValues.C1);
                }
                if (planValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 6).Value = monthlyPlanValues.C1;
                    contentRowFirst.Cell(contentCellIndex + 8).Value = 0 - monthlyPlanValues.C1;
                }
                if (recordValues != null && planValues != null)
                {
                    contentRowFirst.Cell(contentCellIndex + 8).Value = monthlyRecordValues.C1 - monthlyPlanValues.C1;
                }


                contentRowIndex++;



            }
            contentRowIndex++;
            IXLRow contentRowSecond = ws.Row(contentRowIndex++);

            for (int i = 0; i < 10; i++)
            {
                contentRowSecond.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowSecond.Cell(contentCellIndex + i).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                contentRowSecond.Cell(contentCellIndex + i).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            }

            contentRowSecond.Cell(contentCellIndex).Value = String.Empty;
            contentRowSecond.Cell(contentCellIndex + 1).Value = "Итого:";
            contentRowSecond.Cell(contentCellIndex + 2).Value = model.PlanValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 3).Value = model.RecordValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 4).Value = model.RecordValues.Sum(a => a.C1) - model.PlanValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 5).Value = string.Format("{0:F2}", model.RecordValues.Sum(a => a.C1) * 100 / model.PlanValues.Sum(a => a.C1));

            contentRowSecond.Cell(contentCellIndex + 6).Value = model.MonthlyPlanValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 7).Value = model.MonthlyRecordValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 8).Value = model.MonthlyRecordValues.Sum(a => a.C1) - model.MonthlyPlanValues.Sum(a => a.C1);
            contentRowSecond.Cell(contentCellIndex + 9).Value = string.Format("{0:F2}", model.MonthlyRecordValues.Sum(a => a.C1) * 100 / model.MonthlyPlanValues.Sum(a => a.C1));

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

