            headerRow2.Cells(cellIndex, cellIndex + 6).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            headerRow3.Cells(cellIndex, cellIndex + 6).Style.Font.Bold = true;
            headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            headerRow1.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            headerRow2.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            headerRow3.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(7).Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(9).Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Columns(cellIndex, cellIndex + 5).Width = 10;
            headerRow1.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;
            headerRow2.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;
            headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;

            var rows = IoCHelper.GetInstance<Report42RowService>().GetAsRenderModel();

            var rowIndex = 10;

            foreach (var parentRow in rows.Where(a => a.ParentId == null))
            {
                // setparent
                if (rootItem.ContainsKey(parentRow.Id))
                {
                    var row = rootItem[parentRow.Id];
                    IXLRow contentRowFirst = ws.Row(rowIndex);
                    contentRowFirst.Cells(1, 2).Style.Font.Bold = true;
                    contentRowFirst.Cell(1).Value = index++;
                    contentRowFirst.Cell(cellIndex - 1).Value = parentRow.Name;
                    contentRowFirst.Cell(cellIndex).Value = row.C1 + row.C2 + row.C3 + row.C4 + row.C5;
                    contentRowFirst.Cell(cellIndex + 1).Value = row.C1;
                    contentRowFirst.Cell(cellIndex + 2).Value = row.C2;
                    contentRowFirst.Cell(cellIndex + 3).Value = row.C3;
                    contentRowFirst.Cell(cellIndex + 4).Value = row.C4;
                    contentRowFirst.Cell(cellIndex + 5).Value = row.C5;
                    contentRowFirst.Cells(1, model.Report.Count * 6 + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    rowIndex++;
                }

                foreach (var childrenRow in rows.Where(a => a.ParentId == parentRow.Id))
                {
                    //Sets children
                    if (rootItem.ContainsKey(childrenRow.Id))
                    {
                        var childRow = rootItem[childrenRow.Id];
                        IXLRow contentRowSecond = ws.Row(rowIndex);
                        contentRowSecond.Cell(cellIndex - 1).Value = childrenRow.Name;
                        contentRowSecond.Cell(cellIndex).Value = childRow.C1 + childRow.C2 + childRow.C3 + childRow.C4 + childRow.C5;
                        contentRowSecond.Cell(cellIndex + 1).Value = childRow.C1;
                        contentRowSecond.Cell(cellIndex + 2).Value = childRow.C2;
                        contentRowSecond.Cell(cellIndex + 3).Value = childRow.C3;
                        contentRowSecond.Cell(cellIndex + 4).Value = childRow.C4;
                        contentRowSecond.Cell(cellIndex + 5).Value = childRow.C5;
                        contentRowSecond.Cells(1, model.Report.Count * 6 + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        rowIndex++;
                    }
                }
            }
            cellIndex += 6;

            foreach (var item in model.Report)
            {
                if (item.Key != model.OrganizationId)
                {

                    ws.Range(5, cellIndex, 5, cellIndex + 5).Merge();
                    headerRow1.Cell(cellIndex).Value = _organizationService.ByID(item.Key).GetCurrentLocale().ShortName;
                    ws.Range(6, cellIndex, 9, cellIndex).Merge();
                    headerRow2.Cell(cellIndex).Value = "Всего";
                    ws.Range(6, cellIndex + 1, 7, cellIndex + 5).Merge();
                    headerRow2.Cell(cellIndex + 1).Value = "срок эксплуатации  по  годам";
                    ws.Range(8, cellIndex + 1, 9, cellIndex + 1).Merge();
                    headerRow3.Cell(cellIndex + 1).Value = "до 5 лет";
                    ws.Range(8, cellIndex + 2, 9, cellIndex + 2).Merge();
                    headerRow3.Cell(cellIndex + 2).Value = "5-10 лет";
                    ws.Range(8, cellIndex + 3, 9, cellIndex + 3).Merge();
                    headerRow3.Cell(cellIndex + 3).Value = "10-15 лет";
                    ws.Range(8, cellIndex + 4, 9, cellIndex + 4).Merge();
                    headerRow3.Cell(cellIndex + 4).Value = "15-25 лет";
                    ws.Range(8, cellIndex + 5, 9, cellIndex + 5).Merge();
                    headerRow3.Cell(cellIndex + 5).Value = "свыше 25 лет";
                    headerRow1.Cells(cellIndex, cellIndex + 6).Style.Font.Bold = true;
                    headerRow1.Cells(cellIndex, cellIndex + 6).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    headerRow1.Cells(cellIndex, cellIndex + 6).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    headerRow2.Cells(cellIndex, cellIndex + 6).Style.Font.Bold = true;
                    headerRow2.Cells(cellIndex, cellIndex + 6).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    headerRow2.Cells(cellIndex, cellIndex + 6).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    headerRow3.Cells(cellIndex, cellIndex + 6).Style.Font.Bold = true;
                    headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    headerRow1.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    headerRow2.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    headerRow3.Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(7).Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(9).Cells(cellIndex, cellIndex + 5).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Columns(cellIndex, cellIndex + 5).Width = 10;
                    headerRow1.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;
                    headerRow2.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;
                    headerRow3.Cells(cellIndex, cellIndex + 6).Style.Alignment.WrapText = true;

                    rowIndex = 10;

                    foreach (var parentRow in rows.Where(a => a.ParentId == null))
                    {
                        if (item.Value.ContainsKey(parentRow.Id))
                        {
                            var row = item.Value[parentRow.Id];
                            IXLRow contentRowFirst = ws.Row(rowIndex);
                            contentRowFirst.Cells(1, 2).Style.Font.Bold = true;
                            contentRowFirst.Cell(cellIndex).Value = row.C1 + row.C2 + row.C3 + row.C4 + row.C5;
                            contentRowFirst.Cell(cellIndex + 1).Value = row.C1;
                            contentRowFirst.Cell(cellIndex + 2).Value = row.C2;
                            contentRowFirst.Cell(cellIndex + 3).Value = row.C3;
                            contentRowFirst.Cell(cellIndex + 4).Value = row.C4;
                            contentRowFirst.Cell(cellIndex + 5).Value = row.C5;
                            contentRowFirst.Cells(1, model.Report.Count * 6 + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                            rowIndex++;
                        }

                        foreach (var childrenRow in rows.Where(a => a.ParentId == parentRow.Id))
                        {
                            if (item.Value.ContainsKey(childrenRow.Id))
                            {
                                var childRow = item.Value[childrenRow.Id];
                                IXLRow contentRowSecond = ws.Row(rowIndex);
                                contentRowSecond.Cell(cellIndex).Value = childRow.C1 + childRow.C2 + childRow.C3 + childRow.C4 + childRow.C5;
                                contentRowSecond.Cell(cellIndex + 1).Value = childRow.C1;
                                contentRowSecond.Cell(cellIndex + 2).Value = childRow.C2;
                                contentRowSecond.Cell(cellIndex + 3).Value = childRow.C3;
                                contentRowSecond.Cell(cellIndex + 4).Value = childRow.C4;
                                contentRowSecond.Cell(cellIndex + 5).Value = childRow.C5;
                                contentRowSecond.Cells(1, model.Report.Count * 6 + 2).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                                rowIndex++;
                            }
                        }
                    }
                    cellIndex += 6;
                }
            }

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        public static MemoryStream AsExcelStream(this Report43SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report43Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} - {3} чоракларда баланс хисоботининг 190 -катор ёйилмаси.", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Content

            int contentRowIndex = 7,
                contentCellIndex = 1;

            foreach (var item in model.Values)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                contentRowFirst.Cells(1, 6).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

                contentRowFirst.Cell(contentCellIndex).Style.Font.Bold = true;
                contentRowFirst.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                contentRowFirst.Cell(contentCellIndex).Value = item.OrganizationName;

                foreach (var val in item.Values)
                {
                    IXLRow contentRowSecond = ws.Row(contentRowIndex + 1);
                    ws.Range(contentRowIndex + 1, contentCellIndex, contentRowIndex + 1, contentCellIndex + 4).Merge();
                    contentRowSecond.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentRowSecond.Cell(contentCellIndex).Style.Font.Bold = true;
                    contentRowSecond.Cells(1, 6).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowSecond.Cells(1, 6).Style.Fill.BackgroundColor = XLColor.FromHtml("#C8C7C8");
                    contentRowSecond.Cell(contentCellIndex).Value = (int)val.Quarter + " - чорак ҳолатига";

                    contentRowIndex++;

                    var index = 1;
                    foreach (var value in val.Values)
                    {
                        IXLRow contentRowThird = ws.Row(contentRowIndex + 1);

                        contentRowThird.Cells(1, 6).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

                        contentRowThird.Cell(contentCellIndex + 1).Value = index;
                        contentRowThird.Cell(contentCellIndex + 2).Value = value.C1;
                        contentRowThird.Cell(contentCellIndex + 3).Value = value.C2;
                        contentRowThird.Cell(contentCellIndex + 4).Value = value.C3;
                        contentRowThird.Cell(contentCellIndex + 5).Value = String.Format("{0:dd/MM/yyyy}", value.C4);
                        contentRowIndex++;
                        index++;
                    }
                }
                contentRowIndex++;

            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

