        public static MemoryStream AsExcelStream(this Report47SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report47Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} - {3} чоракларда баланс хисоботининг 720 -катор ёйилмаси. Меҳнатга ҳақ тўлаш бўйича қарздорлик", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            var dictionary = new Dictionary<int, string[]>();

            dictionary.Add(1, new[] { "Январь", "Февраль", "Март" });
            dictionary.Add(2, new[] { "Апрель", "Май", "Июнь" });
            dictionary.Add(3, new[] { "Июль", "Август", "Сентябрь" });
            dictionary.Add(4, new[] { "Октябрь", "Ноябрь", "Декабрь" });

            var months = new string[3];

            var fromQuarter = (int)model.FromQuarter;
            var toQuarter = (int)model.ToQuarter;
            var quarters = new List<int>();
            for (int i = fromQuarter; i <= toQuarter; i++)
            {
                quarters.Add(i);
            }

            #region Header

            IXLRow firstHeaderRow = ws.Row(6);
            IXLRow secondHeaderRow = ws.Row(7);
            int cellIndex = 3;

            foreach (var quarter in quarters)
            {
                months = dictionary[quarter];
                secondHeaderRow.Cell(cellIndex).Value = string.Format("{0}", months[0]);
                secondHeaderRow.Cell(cellIndex + 1).Value = string.Format("{0}", months[1]);
                secondHeaderRow.Cell(cellIndex + 2).Value = string.Format("{0}", months[2]);
                cellIndex += 3;
            }

            ws.Range(2, 1, 4, (((toQuarter - fromQuarter) + 1) * 3 + 2)).Merge();
            ws.Range(6, 3, 6, (((toQuarter - fromQuarter) + 1) * 3 + 2)).Merge();
            //firstHeaderRow.Cell(6).Style.Font.Bold = true;
            for (int i = 0; i < (((toQuarter - fromQuarter) + 1) * 3); i++)
            {
                firstHeaderRow.Cell(3 + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                secondHeaderRow.Cell(3 + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            }

            #endregion

            #region Content

            int contentRowIndex = 8,
                contentCellIndex = 1,
                index = 1;

            foreach (var item in model.Values)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                for (int i = 0; i < (((toQuarter - fromQuarter) + 1) * 3 + 2); i++)
                {
                    contentRowFirst.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                }

                contentRowFirst.Cell(contentCellIndex).Value = index;
                contentRowFirst.Cell(contentCellIndex + 1).Style.Font.Bold = true;
                contentRowFirst.Cell(contentCellIndex + 1).Value = item.OrganizationName;
                var counter = 2;
                if (quarters.Contains(1))
                {
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C1;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C2;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C3;
                    counter++;
                }
                if (quarters.Contains(2))
                {
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C4;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C5;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C6;
                    counter++;
                }
                if (quarters.Contains(3))
                {
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C7;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C8;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C9;
                    counter++;
                }
                if (quarters.Contains(4))
                {
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C10;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C11;
                    counter++;
                    contentRowFirst.Cell(contentCellIndex + counter).Value = item.C12;
                    counter++;
                }

                contentRowIndex++;
                index++;
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

