        public static MemoryStream AsExcelStream(this Report52SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report52Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} - {3} чоракларда баланс хисоботининг 220-катор ёйилмаси. \"Харидор ва буюртмачиларнинг қарзи\"", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Content

            int contentRowIndex = 7,
                contentCellIndex = 1;

            foreach (var item in model.Values)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                for (int i = 0; i < 4; i++)
                {
                    contentRowFirst.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                }

                contentRowFirst.Cell(contentCellIndex).Style.Font.Bold = true;
                contentRowFirst.Cell(contentCellIndex).Value = item.OrganizationName;

                foreach (var val in item.Values)
                {
                    IXLRow contentRowSecond = ws.Row(contentRowIndex + 1);
                    ws.Range(contentRowIndex + 1, contentCellIndex, contentRowIndex + 1, contentCellIndex + 5).Merge();
                    contentRowSecond.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentRowSecond.Cell(contentCellIndex).Style.Font.Bold = true;
                    for (int i = 0; i < 7; i++)
                    {
                        contentRowSecond.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSecond.Cell(contentCellIndex + i).Style.Fill.BackgroundColor = XLColor.FromHtml("#C8C7C8");
                    }
                    contentRowSecond.Cell(contentCellIndex).Value = (int)val.Quarter + " - чорак ҳолатига";

                    contentRowIndex++;

                    var index = 1;
                    foreach (var value in val.Values)
                    {
                        IXLRow contentRowThird = ws.Row(contentRowIndex + 1);

                        for (int i = 1; i < 8; i++)
                        {
                            contentRowSecond.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                            contentRowThird.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        }

                        contentRowThird.Cell(contentCellIndex + 1).Value = index;
                        contentRowThird.Cell(contentCellIndex + 2).Value = value.OrganizationName;
                        contentRowThird.Cell(contentCellIndex + 3).Value = value.C1;
                        contentRowThird.Cell(contentCellIndex + 4).Value = value.C2;
                        contentRowThird.Cell(contentCellIndex + 5).Value = value.C3;
                        contentRowThird.Cell(contentCellIndex + 6).Value = value.C4;
                        contentRowIndex++;
                        index++;
                    }
                    IXLRow contentRowSum = ws.Row(contentRowIndex + 1);
                    contentRowSum.Cell(contentCellIndex + 2).Value = "Жами";
                    contentRowSum.Cell(contentCellIndex + 3).Value = val.Values.Sum(a => a.C1);
                    contentRowSum.Cell(contentCellIndex + 4).Value = val.Values.Sum(a => a.C2);
                    for (int i = 1; i < 8; i++)
                    {
                        contentRowSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSum.Cell(i).Style.Font.Bold = true;
                        contentRowSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    }

                }
                contentRowIndex++;

            }

            IXLRow contentRowAllSum = ws.Row(contentRowIndex + 1);
            contentRowAllSum.Cell(contentCellIndex + 2).Value = "Хаммаси";
            contentRowAllSum.Cell(contentCellIndex + 3).Value = model.Values.Sum(a => a.Values.Sum(b => b.Values.Sum(c => c.C1)));
            contentRowAllSum.Cell(contentCellIndex + 4).Value = model.Values.Sum(a => a.Values.Sum(b => b.Values.Sum(c => c.C2)));
            for (int i = 1; i < 8; i++)
            {
                contentRowAllSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowAllSum.Cell(i).Style.Font.Bold = true;
                contentRowAllSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        public static MemoryStream AsExcelStream(this Report53SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report53Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} - {3} чоракларда баланс хисоботининг 240-катор ёйилмаси. \"Шўъба ва қарам хўжаликларнинг қарзи\"", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Content

            int contentRowIndex = 7,
                contentCellIndex = 1;

            foreach (var item in model.Values)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                for (int i = 0; i < 4; i++)
                {
                    contentRowFirst.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                }

                contentRowFirst.Cell(contentCellIndex).Style.Font.Bold = true;
                contentRowFirst.Cell(contentCellIndex).Value = item.OrganizationName;

                foreach (var val in item.Values)
                {
                    IXLRow contentRowSecond = ws.Row(contentRowIndex + 1);
                    ws.Range(contentRowIndex + 1, contentCellIndex, contentRowIndex + 1, contentCellIndex + 5).Merge();
                    contentRowSecond.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentRowSecond.Cell(contentCellIndex).Style.Font.Bold = true;
                    for (int i = 0; i < 7; i++)
                    {
                        contentRowSecond.Cell(contentCellIndex + i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSecond.Cell(contentCellIndex + i).Style.Fill.BackgroundColor = XLColor.FromHtml("#C8C7C8");
                    }
                    contentRowSecond.Cell(contentCellIndex).Value = (int)val.Quarter + " - чорак ҳолатига";

                    contentRowIndex++;

                    var index = 1;
                    foreach (var value in val.Values)
                    {
                        IXLRow contentRowThird = ws.Row(contentRowIndex + 1);

                        for (int i = 1; i < 8; i++)
                        {
                            contentRowSecond.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                            contentRowThird.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        }

                        contentRowThird.Cell(contentCellIndex + 1).Value = index;
                        contentRowThird.Cell(contentCellIndex + 2).Value = value.OrganizationName;
                        contentRowThird.Cell(contentCellIndex + 3).Value = value.C1;
                        contentRowThird.Cell(contentCellIndex + 4).Value = value.C2;
                        contentRowThird.Cell(contentCellIndex + 5).Value = value.C3;
                        contentRowThird.Cell(contentCellIndex + 6).Value = value.C4;
                        contentRowIndex++;
                        index++;
                    }
                    IXLRow contentRowSum = ws.Row(contentRowIndex + 1);
                    contentRowSum.Cell(contentCellIndex + 2).Value = "Жами";
                    contentRowSum.Cell(contentCellIndex + 3).Value = val.Values.Sum(a => a.C1);
                    contentRowSum.Cell(contentCellIndex + 4).Value = val.Values.Sum(a => a.C2);
                    for (int i = 1; i < 8; i++)
                    {
                        contentRowSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSum.Cell(i).Style.Font.Bold = true;
                        contentRowSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    }

                }
                contentRowIndex++;

            }

            IXLRow contentRowAllSum = ws.Row(contentRowIndex + 1);
            contentRowAllSum.Cell(contentCellIndex + 2).Value = "Хаммаси";
            contentRowAllSum.Cell(contentCellIndex + 3).Value = model.Values.Sum(a => a.Values.Sum(b => b.Values.Sum(c => c.C1)));
            contentRowAllSum.Cell(contentCellIndex + 4).Value = model.Values.Sum(a => a.Values.Sum(b => b.Values.Sum(c => c.C2)));
            for (int i = 1; i < 8; i++)
            {
                contentRowAllSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowAllSum.Cell(i).Style.Font.Bold = true;
                contentRowAllSum.Cell(i).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

