        public static MemoryStream AsExcelStream(this Report66SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report66Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            ws.Range(2, 1, 3, model.Values.FirstOrDefault().Values.ToList().Count + 3).Merge();
            titleRow.Cell(1).Value = string.Format("{0} буйича {1} йил {2} - {3} чоракларда холатига ички дебитор ва кредиторлар руйхати", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Header
            IXLRow headerRow = ws.Row(6);
            headerRow.Cell(1).Value = "№";
            headerRow.Cell(2).Value = "Д-т/К-т";
            headerRow.Cell(3).Value = "Жами";
            headerRow.Cells(1, 3).Style.Font.Bold = true;
            headerRow.Cells(1, 3).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            headerRow.Cells(1, 3).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            headerRow.Cells(1, 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Column(2).Width = 15;
            var cellIndex = 4;
            foreach (var item in model.Values.FirstOrDefault().Values)
            {
                headerRow.Cell(cellIndex).Value = item.OrganizationName;
                headerRow.Cell(cellIndex).Style.Font.Bold = true;
                headerRow.Cell(cellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                headerRow.Cell(cellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                headerRow.Cell(cellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Column(cellIndex).Width = 15;
                ws.Row(6).Height = 30;
                ws.Column(cellIndex).Style.Alignment.WrapText = true;
                cellIndex++;
            }
            #endregion

            #region Content
            var index = 1;
            var contentRowIndex = 7;
            foreach (var item in model.Values)
            {
                var contentCellIndex = 1;
                IXLRow contentRowFirst = ws.Row(contentRowIndex);
                contentRowFirst.Cell(contentCellIndex).Value = index;
                contentCellIndex++;
                contentRowFirst.Cell(contentCellIndex).Value = item.OrganizationName;
                contentRowFirst.Cell(contentCellIndex).Style.Alignment.WrapText = true;
                contentCellIndex++;
                contentRowFirst.Cell(contentCellIndex).Value = item.Values.Sum(a => a.C);
                contentRowFirst.Cell(contentCellIndex).Style.Font.Bold = true;
                contentCellIndex++;
                contentRowFirst.Cells(1, 3).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                contentRowFirst.Cells(1, 3).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                contentRowFirst.Cells(1, 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                foreach (var subItem in item.Values)
                {
                    contentRowFirst.Cell(contentCellIndex).Value = subItem.C;
                    contentRowFirst.Cell(contentCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRowFirst.Cell(contentCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentRowFirst.Cell(contentCellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentCellIndex++;
                }
                contentRowIndex++;
                index++;
            }
            var sumCellIndex = 1;
            IXLRow sumRow = ws.Row(contentRowIndex);
            sumCellIndex++;
            sumRow.Cell(sumCellIndex).Value = "Жами";
            sumRow.Cell(sumCellIndex).Style.Font.Bold = true;
            sumCellIndex++;
            sumRow.Cell(sumCellIndex).Value = model.Values.Sum(a => a.Values.Sum(b => b.C));
            sumRow.Cell(sumCellIndex).Style.Font.Bold = true;
            sumCellIndex++;
            sumRow.Cells(1, 3).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            sumRow.Cells(1, 3).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            sumRow.Cells(1, 3).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);

            foreach (var val in model.Values.FirstOrDefault().Values)
            {
                double? temp = 0;
                foreach (var item in model.Values)
                {
                    temp += item.Values.FirstOrDefault(a => a.OrganizationId == val.OrganizationId).C;
                }
                sumRow.Cell(sumCellIndex).Value = temp;
                sumRow.Cell(sumCellIndex).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                sumRow.Cell(sumCellIndex).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                sumRow.Cell(sumCellIndex).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                sumCellIndex++;
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

