        public static MemoryStream AsExcelStream(this Report68RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report68Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("Отчет о выполнении плана ремонта и содержания дорог за {0} {1} год по {2}", model.Month.AsEnumMember().Description, model.Year, model.OrganizationName);

            #endregion

            ws.Row(4).Cell(5).Value = string.Format("План на {0} год", model.Year - 1);
            ws.Row(5).Cell(7).Value = string.Format("в том числе за отчетный {0} месяц", model.Month.AsEnumMember().Description);
            ws.Row(5).Cell(9).Value = string.Format("в том числе за отчетный {0} месяц", model.Month.AsEnumMember().Description);
            ws.Row(5).Cell(11).Value = string.Format("в том числе за отчетный {0} месяц", model.Month.AsEnumMember().Description);
            ws.Row(5).Cell(13).Value = string.Format("в том числе за отчетный {0} месяц", model.Month.AsEnumMember().Description);

            var contentRowIndex = 6;

            var renderModel = IoCHelper.GetInstance<Report68RecordService>().GetRenderModelPlan(model.Year, model.Month, model.OrganizationId);
            var rows = IoCHelper.GetInstance<Report68RowService>().AllAsQueryable.OrderBy(a => a.Order);
            Report68PlanRowValueViewModel previousYearPlanValues = null;
            Report68PlanRowValueViewModel currentYearPlanValues = null;
            Report68PlanRowValueViewModel planValues = null;
            Report68RowValueViewModel beginingOfYearValues = null;

            foreach (var row in rows)
            {
                if (renderModel.previousYearPlan != null)
                    previousYearPlanValues = renderModel.previousYearPlan.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                if (renderModel.currentYearPlan != null)
                    currentYearPlanValues = renderModel.currentYearPlan.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                if (renderModel.plan != null)
                    planValues = renderModel.plan.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                if (renderModel.beginingOfYear != null)
                    beginingOfYearValues = renderModel.beginingOfYear.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                var rowValues = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                ws.Row(contentRowIndex).Cells(1, 13).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 13).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 13).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 13).Style.Font.FontColor = XLColor.FromHtml(row.Color);
                ws.Row(contentRowIndex).Cell(4).Style.Font.FontColor = XLColor.FromHtml("#000000");
                ws.Row(contentRowIndex).Cell(4).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                if (row.IsBold)
                    ws.Row(contentRowIndex).Cells(1, 13).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cells(1, 13).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cell(1).Value = (int)row.Code1;
                ws.Row(contentRowIndex).Cell(2).Value = ((int)row.Code2) == 0 ? "'00" : ((int)row.Code2).AsString();
                ws.Row(contentRowIndex).Cell(3).Value = ((int)row.Code3) == 0 ? "'000" : ((int)row.Code3).AsString();
                ws.Row(contentRowIndex).Cell(4).Value = rowValues.RowName;
                if (previousYearPlanValues != null)
                    ws.Row(contentRowIndex).Cell(5).Value = previousYearPlanValues.C;
                if (currentYearPlanValues != null)
                    ws.Row(contentRowIndex).Cell(6).Value = currentYearPlanValues.C;
                if (planValues != null)
                    ws.Row(contentRowIndex).Cell(7).Value = planValues.C;
                ws.Row(contentRowIndex).Cell(8).Value = beginingOfYearValues._C1;
                ws.Row(contentRowIndex).Cell(10).Value = beginingOfYearValues._C2;
                ws.Row(contentRowIndex).Cell(12).Value = beginingOfYearValues._C3;
                ws.Row(contentRowIndex).Cell(9).Value = rowValues.C1;
                ws.Row(contentRowIndex).Cell(11).Value = rowValues.C2;
                ws.Row(contentRowIndex).Cell(13).Value = rowValues.C3;
                contentRowIndex++;
            }

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

