        public static MemoryStream AsExcelStream(this Report69SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report69Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} бўйича {1} йил {2} - {3} чоракларда баланс хисоботининг 280-катор ёйилмаси. Мақсадли давлат жам-армаларига тўловлар бўйича қарздорлик", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Content

            int contentCellIndex = 1;

            ws.Row(7).Cells(1, model.Taxs.Count() + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(7).Cells(1, model.Taxs.Count() + 1).Style.Font.Bold = true;
            ws.Row(7).Cells(1, model.Taxs.Count() + 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Columns(1, model.Taxs.Count()).Width = ws.Column(1).Width;
            foreach (var item in model.Taxs)
            {
                ws.Row(7).Cell(contentCellIndex + 1).Value = item.Name;
                contentCellIndex++;
            }

            int contentRowIndex = 8;

            foreach (var item in model.Result)
            {
                contentCellIndex = 1;
                ws.Row(contentRowIndex).Cells(1, item.Value.RowValues.Count + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cell(1).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cell(1).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cells(1, item.Value.RowValues.Count + 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cell(1).Value = IoCHelper.GetInstance<OrganizationService>().ByID(item.Key).GetCurrentLocale().ShortName;
                foreach (var row in item.Value.RowValues)
                {
                    ws.Row(contentRowIndex).Cell(contentCellIndex + 1).Value = row.C1;
                    contentCellIndex++;
                }
                contentRowIndex++;
            }

            contentCellIndex = 1;
            ws.Range(contentRowIndex, 1, contentRowIndex + 1, 1).Merge();
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cell(1).Value = "Жами".Localize();

            double? total = 0;

            foreach (var item in model.Result.Select(a => a.Value)
                                                .SelectMany(a => a.RowValues)
                                                .GroupBy(a => a.TaxId))
            {
                total += item.Sum(b => b.C1);
                ws.Row(contentRowIndex).Cell(contentCellIndex + 1).Value = item.Sum(a => a.C1);
                contentCellIndex++;
            }
            contentRowIndex++;

            ws.Range(contentRowIndex, 2, contentRowIndex, model.Taxs.Count() + 1).Merge();
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, model.Taxs.Count() + 1).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cell(2).Value = total;

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

