        public static MemoryStream AsExcelStream(this Report203SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report203Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("Информация о выполнении планов по экономии электрической и тепловой энергии по {0} в разрезе по предприятиям за {1} - {2} {3} года", model.OrganizationName, model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description, model.Year);

            #endregion

            #region Content

            var organization = IoCHelper.GetInstance<OrganizationService>().ByID(model.OrganizationId);

            int contentRowIndex = 9,
                contentCellIndex = 1;

            int index = 1;
            foreach (var item in organization.Children)
            {
                IXLRow contentRowFirst = ws.Row(contentRowIndex);

                ws.Range(contentRowIndex, 1, contentRowIndex + 1, 1).Merge();
                ws.Range(contentRowIndex, 2, contentRowIndex + 1, 2).Merge();
                ws.Range(contentRowIndex, 10, contentRowIndex + 1, 10).Merge();
                ws.Row(contentRowIndex).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;

                contentRowFirst.Cell(1).Value = index++;
                contentRowFirst.Cell(2).Value = item.GetCurrentLocale().ShortName;
                ws.Row(contentRowIndex).Cell(3).Value = "Электроэнергия, (тыс.кВт час)";
                ws.Row(contentRowIndex + 1).Cell(3).Value = "Тепловая энергия. (Гкал)";
                var recordValues = model.RecordValues.FirstOrDefault(a => a.OrganizationId == item.Id);
                var planValues = model.PlanValues.Where(a => a.OrganizationId == item.Id).FirstOrDefault();
                double? rC1 = 0, rC2 = 0, rC3 = 0, rC4 = 0;
                double? pC1 = 0, pC2 = 0, pC3 = 0, pC4 = 0;
                if (recordValues != null)
                {
                    rC1 = recordValues.C1; rC2 = recordValues.C2; rC3 = recordValues.C3; rC4 = recordValues.C4;
                    ws.Row(contentRowIndex).Cell(5).Value = recordValues.C1;
                    ws.Row(contentRowIndex).Cell(8).Value = recordValues.C2;
                    ws.Row(contentRowIndex + 1).Cell(5).Value = recordValues.C3;
                    ws.Row(contentRowIndex + 1).Cell(8).Value = recordValues.C4;
                    ws.Row(contentRowIndex).Cell(10).Value = recordValues.FailureReason;
                }
                if (planValues != null)
                {
                    pC1 = planValues.C1; pC2 = planValues.C2; pC3 = planValues.C3; pC4 = planValues.C4;
                    ws.Row(contentRowIndex).Cell(4).Value = planValues.C1;
                    ws.Row(contentRowIndex).Cell(7).Value = planValues.C2;
                    ws.Row(contentRowIndex + 1).Cell(4).Value = planValues.C3;
                    ws.Row(contentRowIndex + 1).Cell(7).Value = planValues.C4;
                }
                ws.Row(contentRowIndex).Cell(6).Value = rC1 - pC1;
                ws.Row(contentRowIndex).Cell(9).Value = rC2 - pC3;
                ws.Row(contentRowIndex + 1).Cell(6).Value = rC3 - pC3;
                ws.Row(contentRowIndex + 1).Cell(9).Value = rC4 - pC4;

                contentRowIndex++;
                contentRowIndex++;

            }
            contentRowIndex++;
            IXLRow contentRowSecond = ws.Row(contentRowIndex++);

            ws.Range(contentRowIndex, 1, contentRowIndex + 1, 1).Merge();
            ws.Range(contentRowIndex, 2, contentRowIndex + 1, 2).Merge();
            ws.Range(contentRowIndex, 10, contentRowIndex + 1, 10).Merge();
            ws.Row(contentRowIndex).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 10).Style.Font.Bold = true;
            ws.Row(contentRowIndex + 1).Cells(1, 10).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cell(1).Value = String.Empty;
            ws.Row(contentRowIndex).Cell(2).Value = "Итого:";
            ws.Row(contentRowIndex).Cell(3).Value = "Электроэнергия, (тыс.кВт час)";
            ws.Row(contentRowIndex + 1).Cell(3).Value = "Тепловая энергия. (Гкал)";

            ws.Row(contentRowIndex).Cell(5).Value = model.RecordValues.Sum(a => a.C1);
            ws.Row(contentRowIndex).Cell(8).Value = model.RecordValues.Sum(a => a.C2);
            ws.Row(contentRowIndex + 1).Cell(5).Value = model.RecordValues.Sum(a => a.C3);
            ws.Row(contentRowIndex + 1).Cell(8).Value = model.RecordValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(4).Value = model.PlanValues.Sum(a => a.C1);
            ws.Row(contentRowIndex).Cell(7).Value = model.PlanValues.Sum(a => a.C2);
            ws.Row(contentRowIndex + 1).Cell(4).Value = model.PlanValues.Sum(a => a.C3);
            ws.Row(contentRowIndex + 1).Cell(7).Value = model.PlanValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(6).Value = model.RecordValues.Sum(a => a.C1) - model.PlanValues.Sum(a => a.C1);
            ws.Row(contentRowIndex).Cell(9).Value = model.RecordValues.Sum(a => a.C2) - model.PlanValues.Sum(a => a.C2);
            ws.Row(contentRowIndex + 1).Cell(6).Value = model.RecordValues.Sum(a => a.C3) - model.PlanValues.Sum(a => a.C3);
            ws.Row(contentRowIndex + 1).Cell(9).Value = model.RecordValues.Sum(a => a.C4) - model.PlanValues.Sum(a => a.C4);


            wb.Save();

            #endregion
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        public static MemoryStream AsExcelStream(this Report204RecordExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report204Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("Номенклатура грузов для перевозок железнодорожным транспортом по {0} на {1} год", model.OrganizationName, model.Year);

            #endregion

            var rowIndex = 8;
            var index = 1;
            foreach (var item in model.Values)
            {
                IXLRow contentRowFirst = ws.Row(rowIndex);
                contentRowFirst.Cells(1, 7).Style.Font.Bold = true;
                contentRowFirst.Cells(1, 7).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                contentRowFirst.Cell(1).Value = index++;
                contentRowFirst.Cell(2).Value = item.RowName;
                contentRowFirst.Cell(3).Value = item.C1 + item.C2 + item.C3 + item.C4;
                contentRowFirst.Cell(4).Value = item.C1;
                contentRowFirst.Cell(5).Value = item.C2;
                contentRowFirst.Cell(6).Value = item.C3;
                contentRowFirst.Cell(7).Value = item.C4;
                contentRowFirst.Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                rowIndex++;
                foreach (var subItem in item.Children)
                {
                    IXLRow contentRowSecond = ws.Row(rowIndex);
                    contentRowSecond.Cells(1, 7).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRowSecond.Cell(2).Value = subItem.RowName;
                    contentRowSecond.Cell(3).Value = subItem.C1 + subItem.C2 + subItem.C3 + subItem.C4;
                    contentRowSecond.Cell(4).Value = subItem.C1;
                    contentRowSecond.Cell(5).Value = subItem.C2;
                    contentRowSecond.Cell(6).Value = subItem.C3;
                    contentRowSecond.Cell(7).Value = subItem.C4;
                    contentRowSecond.Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    rowIndex++;
                }
            }

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        public static MemoryStream AsExcelStream(this Report204SummaryExportModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report204Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("Номенклатура грузов для перевозок железнодорожным транспортом по подразделениям {0} на {1} год", model.OrganizationName, model.Year);

            #endregion

            var _organizationService = IoCHelper.GetInstance<OrganizationService>();

            var rootItem = model.Report[model.OrganizationId];
            var index = 1;

            var rows = IoCHelper.GetInstance<Report204RowService>().GetAsRenderModel();

            var rowIndex = 8;

            var sum = model.Report[-1][-1];
            IXLRow contentRowSum = ws.Row(rowIndex);
            contentRowSum.Cells(1, 7).Style.Font.Bold = true;
            contentRowSum.Cell(2).Value = String.Format("ВСЕГО по {0}", model.OrganizationName);
            contentRowSum.Cell(3).Value = sum.C1 + sum.C2 + sum.C3 + sum.C4;
            contentRowSum.Cell(4).Value = sum.C1;
            contentRowSum.Cell(5).Value = sum.C2;
            contentRowSum.Cell(6).Value = sum.C3;
            contentRowSum.Cell(7).Value = sum.C4;
            contentRowSum.Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            rowIndex++;

            foreach (var parentRow in rows.Where(a => a.ParentId == null))
            {
                // setparent
                if (rootItem.ContainsKey(parentRow.Id))
                {
                    var row = rootItem[parentRow.Id];
                    IXLRow contentRowFirst = ws.Row(rowIndex);
                    contentRowFirst.Cells(1, 7).Style.Font.Bold = true;
                    contentRowFirst.Cell(1).Value = index++;
                    contentRowFirst.Cell(2).Value = parentRow.Name;
                    contentRowFirst.Cell(3).Value = row.C1 + row.C2 + row.C3 + row.C4;
                    contentRowFirst.Cell(4).Value = row.C1;
                    contentRowFirst.Cell(5).Value = row.C2;
                    contentRowFirst.Cell(6).Value = row.C3;
                    contentRowFirst.Cell(7).Value = row.C4;
                    contentRowFirst.Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    rowIndex++;
                }

                foreach (var childrenRow in rows.Where(a => a.ParentId == parentRow.Id))
                {
                    //Sets children
                    if (rootItem.ContainsKey(childrenRow.Id))
                    {
                        var childRow = rootItem[childrenRow.Id];
                        IXLRow contentRowSecond = ws.Row(rowIndex);
                        contentRowSecond.Cell(2).Value = childrenRow.Name;
                        contentRowSecond.Cell(3).Value = childRow.C1 + childRow.C2 + childRow.C3 + childRow.C4;
                        contentRowSecond.Cell(4).Value = childRow.C1;
                        contentRowSecond.Cell(5).Value = childRow.C2;
                        contentRowSecond.Cell(6).Value = childRow.C3;
                        contentRowSecond.Cell(7).Value = childRow.C4;
                        contentRowSecond.Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        rowIndex++;
                    }
                }
            }

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

