        public static MemoryStream AsExcelStream(this Report210RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report210Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            ws.Row(2).Cell(1).Value = string.Format("{0} бўйича {1} {2} йилда рангли металл чиқиндилари топширилиши тўғрисидаги маълумот", model.OrganizationName, model.Month.AsEnumMember().Description, model.Year);

            #endregion

            #region Content

            var plan = IoCHelper.GetInstance<Report210PlanService>().AllAsQueryable.FirstOrDefault(a => a.OrganizationId == model.OrganizationId && a.Year == model.Year && a.Month == model.Month);

            int contentRowIndex = 5;
            double? planC1 = 0;
            if (plan != null)
                planC1 = plan.C1;
            ws.Row(contentRowIndex).Cell(1).Value = model.OrganizationName;
            ws.Row(contentRowIndex).Cell(2).Value = planC1;
            ws.Row(contentRowIndex).Cell(3).Value = model.C1;
            ws.Row(contentRowIndex).Cell(4).Value = model.C1 - planC1;
            if (planC1 != 0)
                ws.Row(contentRowIndex).Cell(5).Value = String.Format("{0:0.##}", model.C1 * 100 / planC1);

            contentRowIndex++;

            wb.Save();

            #endregion
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        public static MemoryStream AsExcelStream(this Report210SummaryRenderModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report210Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title
            var organization = IoCHelper.GetInstance<OrganizationService>().ByID(model.OrganizationId);
            ws.Row(2).Cell(1).Value = string.Format("{0} бўйича {1} {2} йилда рангли металл чиқиндилари топширилиши тўғрисидаги маълумот", organization.GetCurrentLocale().ShortName, model.Month.AsEnumMember().Description, model.Year);

            #endregion

            ws.Row(4).Cell(3).Value = string.Format("{0} - {1} ойлари режаси", model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);
            ws.Row(4).Cell(4).Value = string.Format("{0} - {1} ойлари амалда", model.FromMonth.AsEnumMember().Description, model.ToMonth.AsEnumMember().Description);
            ws.Row(4).Cell(7).Value = string.Format("{0} ойи режаси", model.Month.AsEnumMember().Description);
            ws.Row(4).Cell(8).Value = string.Format("{0} ойи амалда", model.Month.AsEnumMember().Description);

            #region Content

            int contentRowIndex = 5;
            int index = 1;
            double? planC1 = 0;

            foreach (var org in organization.Children)
            {
                ws.Row(contentRowIndex).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cell(2).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cell(1).Value = index++;
                ws.Row(contentRowIndex).Cell(2).Value = org.GetCurrentLocale().ShortName;
                if (model.Interval.Record.ContainsKey(org.Id))
                {
                    planC1 = 0;
                    ws.Row(contentRowIndex).Cell(4).Value = model.Interval.Record[org.Id].C1;
                    if (model.Interval.Plan.ContainsKey(org.Id))
                    {
                        if (model.Interval.Plan[org.Id] != null)
                            planC1 = model.Interval.Plan[org.Id].C1;
                        ws.Row(contentRowIndex).Cell(3).Value = model.Interval.Plan[org.Id].C1;
                        if (planC1 != 0)
                            ws.Row(contentRowIndex).Cell(6).Value = String.Format("{0:0.##}", model.Interval.Record[org.Id].C1 * 100 / planC1);

                    }
                    ws.Row(contentRowIndex).Cell(5).Value = model.Interval.Record[org.Id].C1 - planC1;
                }

                planC1 = 0;
                if (model.Monthly.Record.ContainsKey(org.Id))
                {
                    ws.Row(contentRowIndex).Cell(8).Value = model.Monthly.Record[org.Id].C1;
                    if (model.Monthly.Plan.ContainsKey(org.Id))
                    {
                        if (model.Monthly.Plan[org.Id] != null)
                            planC1 = model.Monthly.Plan[org.Id].C1;
                        ws.Row(contentRowIndex).Cell(7).Value = model.Monthly.Plan[org.Id].C1;
                        if (planC1 != 0)
                            ws.Row(contentRowIndex).Cell(10).Value = String.Format("{0:0.##}", model.Monthly.Record[org.Id].C1 * 100 / planC1);

                    }
                    ws.Row(contentRowIndex).Cell(9).Value = model.Monthly.Record[org.Id].C1 - planC1;
                }
                contentRowIndex++;
            }


            ws.Row(contentRowIndex).Cells(1, 10).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 10).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 10).Style.Font.Bold = true;

            planC1 = 0;
            if (model.Interval.Plan.Sum(a => a.Value.C1) != null)
                planC1 = model.Interval.Plan.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(2).Value = "Итого";
            ws.Row(contentRowIndex).Cell(3).Value = model.Interval.Plan.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(4).Value = model.Interval.Record.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(5).Value = model.Interval.Record.Sum(a => a.Value.C1) - planC1;
            if (planC1 != 0)
                ws.Row(contentRowIndex).Cell(6).Value = String.Format("{0:0.##}", model.Interval.Record.Sum(a => a.Value.C1) * 100 / planC1);

            planC1 = 0;
            if (model.Monthly.Plan.Sum(a => a.Value.C1) != null)
                planC1 = model.Monthly.Plan.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(7).Value = model.Monthly.Plan.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(8).Value = model.Monthly.Record.Sum(a => a.Value.C1);
            ws.Row(contentRowIndex).Cell(9).Value = model.Monthly.Record.Sum(a => a.Value.C1) - planC1;
            if (planC1 != 0)
                ws.Row(contentRowIndex).Cell(10).Value = String.Format("{0:0.##}", model.Monthly.Record.Sum(a => a.Value.C1) * 100 / planC1);

            wb.Save();

            #endregion
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

