        public static MemoryStream AsExcelStream(this Report302SummaryViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report302Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            ws.Row(2).Cell(1).Value = string.Format("{0} тасарруфидаги автомобил йулларида {1} йил {2} - {3} чоракларда содир этилган йул-транспорт ходисалари буйича ХИСОБОТ", model.OrganizationName, model.Year, (int)model.FromQuarter, (int)model.ToQuarter);

            #endregion

            #region Content

            int contentRowIndex = 7;

            foreach (var item in model.Section1Values)
            {
                if (item.Code == ReportRowCode._04)
                    contentRowIndex++;
                ws.Row(contentRowIndex).Cell(3).Value = item.C1;
                ws.Row(contentRowIndex).Cell(4).Value = item.C2;
                ws.Row(contentRowIndex).Cell(5).Value = item.C3;
                contentRowIndex++;
            }


            var originalRange = ws.Range(16, 1, 70, 6);

            contentRowIndex = 16;
            var count = 0;
            foreach (var item in model.Section2Values)
            {

                ws.Row(contentRowIndex).Cell(1).Value = item.OrganizationName;
                contentRowIndex += 3;
                foreach (var subItem in item.Values)
                {
                    ws.Row(contentRowIndex).Cell(4).Value = subItem.C1;
                    ws.Row(contentRowIndex).Cell(5).Value = subItem.C2;
                    contentRowIndex++;
                }
                contentRowIndex += 2;
                count++;
                if (model.Section2Values.Count > count)
                {
                    var destRange = ws.Range(contentRowIndex, 1, contentRowIndex + 54, 6);
                    originalRange.CopyTo(destRange);
                }
            }


            wb.Save();

            #endregion
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

