                ws.Row(contentRowIndex).Cell(7).Value = model.Values.Where(c => c.RowName.Equals("Давлат аҳамиятидаги йўлларда")).Sum(a => a.C6);
                ws.Row(contentRowIndex).Cell(8).Value = model.Values.Where(c => c.RowName.Equals("Давлат аҳамиятидаги йўлларда")).Sum(a => a.C7);
                ws.Row(contentRowIndex).Cell(9).Value = model.Values.Where(c => c.RowName.Equals("Давлат аҳамиятидаги йўлларда")).Sum(a => a.C8);
                contentRowIndex++;

                ws.Range(contentRowIndex, 1, contentRowIndex, 9).Merge();
                ws.Row(contentRowIndex).Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cell(1).Value = "шу жумладан:";
                contentRowIndex++;

                var values = model.Values.GroupBy(a => a.RegionName);

                foreach (var item in values)
                {
                    ws.Range(contentRowIndex, 1, contentRowIndex, 3).Merge();
                    ws.Row(contentRowIndex).Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(contentRowIndex).Cells(1, 9).Style.Fill.BackgroundColor = XLColor.FromHtml("#DFF0D8");
                    ws.Row(contentRowIndex).Cells(1, 9).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    ws.Row(contentRowIndex).Cells(1, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    ws.Row(contentRowIndex).Cells(1, 9).Style.Font.Bold = true;
                    ws.Row(contentRowIndex).Cell(1).Value = item.Key;
                    ws.Row(contentRowIndex).Cell(7).Value = item.Sum(a => a.C6);
                    ws.Row(contentRowIndex).Cell(8).Value = item.Sum(a => a.C7);
                    ws.Row(contentRowIndex).Cell(9).Value = item.Sum(a => a.C8);
                    contentRowIndex++;

                    var items = item.GroupBy(a => a.RowName);

                    foreach (var subItem in items)
                    {
                        IXLRow contentRowFirst = ws.Row(contentRowIndex);
                        ws.Range(contentRowIndex, 1, contentRowIndex, 3).Merge();
                        contentRowFirst.Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowFirst.Cells(1, 9).Style.Fill.BackgroundColor = XLColor.FromHtml("#FCF8E3");
                        contentRowFirst.Cells(1, 9).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        contentRowFirst.Cells(1, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        contentRowFirst.Cells(1, 9).Style.Font.Bold = true;
                        contentRowFirst.Cell(1).Value = subItem.Key;
                        contentRowFirst.Cell(7).Value = subItem.Sum(a => a.C6);
                        contentRowFirst.Cell(8).Value = subItem.Sum(a => a.C7);
                        contentRowFirst.Cell(9).Value = subItem.Sum(a => a.C8);
                        contentRowIndex++;
                        var index = 1;
                        foreach (var val in subItem)
                        {
                            IXLRow contentRowSecond = ws.Row(contentRowIndex);
                            contentRowSecond.Cells(1, 9).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                            contentRowSecond.Cells(1, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                            contentRowSecond.Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                            contentRowSecond.Cell(1).Value = index++;
                            contentRowSecond.Cell(2).Value = val.C1;
                            contentRowSecond.Cell(3).Value = val.C2;
                            contentRowSecond.Cell(4).Value = val.C3;
                            contentRowSecond.Cell(5).Value = val.C4;
                            contentRowSecond.Cell(6).Value = val.C5;
                            contentRowSecond.Cell(7).Value = val.C6;
                            contentRowSecond.Cell(8).Value = val.C7;
                            contentRowSecond.Cell(9).Value = val.C8;
                            contentRowIndex++;
                        }
                    }


                }

            }
            else
            {


                var values = model.Values.GroupBy(a => a.RowName);

                foreach (var item in values)
                {
                    IXLRow contentRowFirst = ws.Row(contentRowIndex);
                    ws.Range(contentRowIndex, 1, contentRowIndex, 3).Merge();
                    contentRowFirst.Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    contentRowFirst.Cells(1, 9).Style.Fill.BackgroundColor = XLColor.FromHtml("#C8C7C8");
                    contentRowFirst.Cells(1, 9).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    contentRowFirst.Cells(1, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRowFirst.Cells(1, 9).Style.Font.Bold = true;
                    contentRowFirst.Cell(1).Value = item.Key;
                    contentRowFirst.Cell(7).Value = item.Sum(a => a.C6);
                    contentRowFirst.Cell(8).Value = item.Sum(a => a.C7);
                    contentRowFirst.Cell(9).Value = item.Sum(a => a.C8);
                    contentRowIndex++;

                    var index = 1;
                    foreach (var val in item)
                    {
                        IXLRow contentRowSecond = ws.Row(contentRowIndex);
                        contentRowSecond.Cells(1, 9).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        contentRowSecond.Cells(1, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        contentRowSecond.Cells(1, 9).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                        contentRowSecond.Cell(1).Value = index++;
                        contentRowSecond.Cell(2).Value = val.C1;
                        contentRowSecond.Cell(3).Value = val.C2;
                        contentRowSecond.Cell(4).Value = val.C3;
                        contentRowSecond.Cell(5).Value = val.C4;
