        public static MemoryStream AsExcelStream(this Report305RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report305Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} тасарруфидаги махаллий ахамиятдаги автомобил йўлларининг қопламалар бўйича {1} йил тақсимоти", model.OrganizationName, model.Year);

            #endregion

            ws.Row(4).Cell(3).Value = string.Format("Йил бошида мавжуд 01.01.{0} йил", model.Year);
            ws.Row(4).Cell(14).Value = string.Format("Йил охирига мавжуд 01.01.{0} йил", model.Year + 1);

            #region Content

            var rows = new Dictionary<int, string>();
            rows.Add(10, "Автомобил йуллари ЖАМИ: (18, 19 каторлар йигиндиси)");
            rows.Add(11, "Цементобетонли");
            rows.Add(12, "Асфалътобетонли");
            rows.Add(13, "Кора копламали");
            rows.Add(14, "Шагалли");
            rows.Add(15, "Тупрок асфалътли");
            rows.Add(18, "ЖАМИ каттик копламали йуллар (11 дан 15 гача сатрлар йигиндиси)");
            rows.Add(19, "Тупрокли");

            int contentRowIndex = 8;


            foreach (var item in model.Values)
            {
                if ((int)item.Code == 11)
                {
                    ws.Row(contentRowIndex).Cell(1).Value = "Шу жумладан";
                    ws.Row(contentRowIndex).Cells(1, 14).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(contentRowIndex).Cell(1).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    ws.Row(contentRowIndex).Cell(1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    contentRowIndex++;
                }
                IXLRow contentRowFirst = ws.Row(contentRowIndex);
                contentRowFirst.Cells(1, 14).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                contentRowFirst.Cells(1, 14).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                contentRowFirst.Cells(1, 14).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                if (item.Code == Enums.ReportRowCode._10 || item.Code == Enums.ReportRowCode._18)
                    ws.Row(contentRowIndex).Cells(1, 14).Style.Font.Bold = true;
                contentRowFirst.Cell(1).Style.Alignment.WrapText = true;
                contentRowFirst.Cell(1).Value = rows[(int)item.Code];
                contentRowFirst.Cell(2).Value = (int)item.Code;
                contentRowFirst.Cell(3).Value = item.C1;
                contentRowFirst.Cell(4).Value = item.C2 + item.C3 + item.C4 + item.C5;
                contentRowFirst.Cell(5).Value = item.C2;
                contentRowFirst.Cell(6).Value = item.C3;
                contentRowFirst.Cell(7).Value = item.C4;
                contentRowFirst.Cell(8).Value = item.C5;
                contentRowFirst.Cell(9).Value = item.C6 + item.C7 + item.C8 + item.C9;
                contentRowFirst.Cell(10).Value = item.C6;
                contentRowFirst.Cell(11).Value = item.C7;
                contentRowFirst.Cell(12).Value = item.C8;
                contentRowFirst.Cell(13).Value = item.C9;
                contentRowFirst.Cell(14).Value = item.C1 + (item.C2 + item.C3 + item.C4 + item.C5) - (item.C6 + item.C7 + item.C8 + item.C9);
                contentRowIndex++;

            }


            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

