        public static MemoryStream AsExcelStream(this Report307RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report307Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} {1} йилдаги хисоботи", model.OrganizationName, model.Year);

            #endregion

            #region Content

            var contentRowIndex = 10;

            foreach (var item in model.Section1Values)
            {
                switch ((int)item.Code)
                {
                    case 11:
                        contentRowIndex = 10;
                        ws.Row(contentRowIndex).Cell(3).Value = item.C1 + item.C2 + item.C3;
                        ws.Row(contentRowIndex).Cell(4).Value = item.C1;
                        ws.Row(contentRowIndex).Cell(5).Value = item.C2;
                        ws.Row(contentRowIndex).Cell(6).Value = item.C3;
