        public static MemoryStream AsExcelStream(this Report310RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report310Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} автомобил йулларида харакат хавфсизлигини таъминлаш ва жихозлаш буйича {1} йил январ-декабр режасининг бажарилиши тугрисида маълумот", model.OrganizationName, model.Year);

            #endregion

            #region Content

            var contentRowIndex = 8;

            var planValues = IoCHelper.GetInstance<Report310PlanService>().AllAsQueryable.FirstOrDefault(a => a.OrganizationId == model.OrganizationId && a.Year == model.Year);
            var rowService = IoCHelper.GetInstance<Report310RowService>().AsObjectQuery().OrderBy(a => a.Order).ToArray();
            var rows = rowService.Where(b => b.ParentId == null)
                .Select(c => new
                {
                    Id = c.Id,
                    Number = c.Number,
                    Name = c.GetCurrentLocale().Name,
                    Unit = c.Unit,
                    Children = rowService.Where(d => d.ParentId == c.Id)
                    .Select(e => new
                    {
                        Id = e.Id,
                        Number = e.Number,
                        Name = e.GetCurrentLocale().Name,
                        Unit = e.Unit,
                    })
                });

            foreach (var row in rows)
            {
                var rowValue = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                ws.Row(contentRowIndex).Cells(1, 19).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 19).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cells(3, 19).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cell(2).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                ws.Row(contentRowIndex).Cell(2).Value = row.Name;
                ws.Row(contentRowIndex).Cell(3).Value = row.Unit;
                ws.Row(contentRowIndex).Cell(6).Value = rowValue.C1;
                ws.Row(contentRowIndex).Cell(7).Value = rowValue.C2;
                ws.Row(contentRowIndex).Cell(10).Value = rowValue.C3;
                ws.Row(contentRowIndex).Cell(11).Value = rowValue.C4;
                ws.Row(contentRowIndex).Cell(14).Value = rowValue.C5;
                ws.Row(contentRowIndex).Cell(15).Value = rowValue.C6;
                ws.Row(contentRowIndex).Cell(18).Value = rowValue.C7;
                ws.Row(contentRowIndex).Cell(19).Value = rowValue.C8;
                if (planValues != null)
                {
                    var plan = planValues.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                    ws.Row(contentRowIndex).Cell(4).Value = plan.C1;
                    ws.Row(contentRowIndex).Cell(5).Value = plan.C2;
                    ws.Row(contentRowIndex).Cell(8).Value = plan.C3;
                    ws.Row(contentRowIndex).Cell(9).Value = plan.C4;
                    ws.Row(contentRowIndex).Cell(12).Value = plan.C5;
                    ws.Row(contentRowIndex).Cell(13).Value = plan.C6;
                    ws.Row(contentRowIndex).Cell(16).Value = plan.C7;
                    ws.Row(contentRowIndex).Cell(17).Value = plan.C8;
                }
                contentRowIndex++;
                foreach (var item in row.Children)
                {
                    var childRowValue = model.RowValues.FirstOrDefault(a => a.RowId == item.Id);
                    ws.Row(contentRowIndex).Cells(1, 19).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(contentRowIndex).Cells(1, 19).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    ws.Row(contentRowIndex).Cells(3, 19).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    ws.Row(contentRowIndex).Cell(2).Style.Alignment.WrapText = true;
                    ws.Row(contentRowIndex).Cell(2).Value = "      " + item.Name;
                    ws.Row(contentRowIndex).Cell(3).Value = item.Unit;
                    ws.Row(contentRowIndex).Cell(6).Value = childRowValue.C1;
                    ws.Row(contentRowIndex).Cell(7).Value = childRowValue.C2;
                    ws.Row(contentRowIndex).Cell(10).Value = childRowValue.C3;
                    ws.Row(contentRowIndex).Cell(11).Value = childRowValue.C4;
                    ws.Row(contentRowIndex).Cell(14).Value = childRowValue.C5;
                    ws.Row(contentRowIndex).Cell(15).Value = childRowValue.C6;
                    ws.Row(contentRowIndex).Cell(18).Value = childRowValue.C7;
                    ws.Row(contentRowIndex).Cell(19).Value = childRowValue.C8;
                    if (planValues != null)
                    {
                        var plan = planValues.RowValues.FirstOrDefault(a => a.RowId == item.Id);
                        ws.Row(contentRowIndex).Cell(4).Value = plan.C1;
                        ws.Row(contentRowIndex).Cell(5).Value = plan.C2;
                        ws.Row(contentRowIndex).Cell(8).Value = plan.C3;
                        ws.Row(contentRowIndex).Cell(9).Value = plan.C4;
                        ws.Row(contentRowIndex).Cell(12).Value = plan.C5;
                        ws.Row(contentRowIndex).Cell(13).Value = plan.C6;
                        ws.Row(contentRowIndex).Cell(16).Value = plan.C7;
                        ws.Row(contentRowIndex).Cell(17).Value = plan.C8;
                    }
                    contentRowIndex++;
                }
            }

            ws.Row(contentRowIndex).Cells(1, 19).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cells(1, 19).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 19).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 19).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cell(2).Value = "Жами харажатлар:";
            ws.Row(contentRowIndex).Cell(3).Value = "м.сум";
            ws.Row(contentRowIndex).Cell(7).Value = model.RowValues.Sum(a => a.C2);
            ws.Row(contentRowIndex).Cell(11).Value = model.RowValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(15).Value = model.RowValues.Sum(a => a.C6);
            ws.Row(contentRowIndex).Cell(19).Value = model.RowValues.Sum(a => a.C8);
            if (planValues != null)
            {
                ws.Row(contentRowIndex).Cell(5).Value = planValues.RowValues.Sum(a => a.C2);
                ws.Row(contentRowIndex).Cell(9).Value = planValues.RowValues.Sum(a => a.C4);
                ws.Row(contentRowIndex).Cell(13).Value = planValues.RowValues.Sum(a => a.C6);
                ws.Row(contentRowIndex).Cell(17).Value = planValues.RowValues.Sum(a => a.C8);
            }
            contentRowIndex++;

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

