            titleRow.Cell(1).Value = string.Format("{0} тасарруфидаги автомобил йулларида харакат хавфсизлигини таъминлаш ва жихозлаш буйича {1} йил январ-декабр режасининг бажарилиши тугрисида маълумот", organization.GetCurrentLocale().ShortName, model.Year);

            #endregion

            #region Content

            var contentRowIndex = 8;
            var rowService = IoCHelper.GetInstance<Report310RowService>().AsObjectQuery().OrderBy(a => a.Order).ToArray();
            var rows = rowService.Where(b => b.ParentId == null)
                .Select(c => new
                {
                    Id = c.Id,
                    Number = c.Number,
                    Name = c.GetCurrentLocale().Name,
                    Unit = c.Unit,
                    Children = rowService.Where(d => d.ParentId == c.Id)
                    .Select(e => new
                    {
                        Id = e.Id,
                        Number = e.Number,
                        Name = e.GetCurrentLocale().Name,
                        Unit = e.Unit,
                    })
                });

            foreach (var row in rows)
            {
                var rowValue = model.Report[model.OrganizationId].Values.FirstOrDefault(a => a.RowId == row.Id);
                var planValue = model.Plan[model.OrganizationId].Values.FirstOrDefault(a => a.RowId == row.Id);
                ws.Row(contentRowIndex).Cells(1, 7).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 7).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cells(3, 7).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(contentRowIndex).Cell(2).Style.Alignment.WrapText = true;
