            ws.Row(contentRowIndex).Cells(1, 19).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cell(1).Value = "Итого";
            var tempRowIds = rows.Where(a => a.MergeableParentId == null).Select(b => b.Id)
                               .ToArray();

            var rowValues = model.Report[model.OrganizationId].Values.Where(a => tempRowIds.Contains(a.RowId));
            var planValues = model.Plan[model.OrganizationId].Values.Where(a => tempRowIds.Contains(a.RowId));

            ws.Row(contentRowIndex).Cell(7).Value = rowValues.Sum(a => a.C2);
            ws.Row(contentRowIndex).Cell(11).Value = rowValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(15).Value = rowValues.Sum(a => a.C6);
            ws.Row(contentRowIndex).Cell(19).Value = rowValues.Sum(a => a.C8);
