        #region Report 316
        public static MemoryStream AsExcelStream(this Report316RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report316Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} умумфойдаланувдаги махаллий ахамиятдаги автомобил йулларини таъмирлаш ва саклаш харажатлари буйича {1} йил ЯНВАР-ДЕКАБРЬ ойлари 2-Д ХИСОБОТИ", model.OrganizationName, model.Year);

            #endregion

            #region Header
            ws.Row(4).Cell(4).Value = string.Format("{0} йил тугалланмаган объектлар хажми", model.Year - 1);
            ws.Row(5).Cell(7).Value = model.OrganizationName;
            ws.Row(5).Cell(15).Value = string.Format("{0} йил тугалланмаган объектлар хажми (гр.8-9-10-11)", model.Year);
            #endregion

            #region Content

            var contentRowIndex = 9;

            var rows = IoCHelper.GetInstance<Report316RowService>().GetAsRenderModel().OrderBy(a => a.Order).ToArray();

            foreach (var row in rows)
            {
                if (row.ParentId == null && row.IsAdditionally == false)
                {
                    var rowValue = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                    if (row.IsBold)
                        ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
                    ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                    ws.Row(contentRowIndex).Cell(2).Value = row.Name;
                    ws.Row(contentRowIndex).Cell(3).Value = row.Code;
                    setValues(ws.Row(contentRowIndex), rowValue);
                    if (rowValue == null)
                    {
                        ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                    }
                    contentRowIndex++;
                    foreach (var childRow in rows.Where(a => a.ParentId == row.Id))
                    {
                        var childRowValue = model.RowValues.FirstOrDefault(a => a.RowId == childRow.Id);
                        if (childRow.IsBold)
                            ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
                        ws.Row(contentRowIndex).Cell(1).Value = childRow.Number;
                        ws.Row(contentRowIndex).Cell(2).Value = "      " + childRow.Name;
                        ws.Row(contentRowIndex).Cell(3).Value = childRow.Code;
                        setValues(ws.Row(contentRowIndex), childRowValue);
                        if (childRowValue == null)
                        {
                            ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                        }
                        contentRowIndex++;
                    }
                }
            }

            ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cells(1, 15).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 15).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 15).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cell(2).Value = "Жами (гр.010+020+030+040+050)";
            var tempRowIds = rows.Where(a => a.ParentId == null && a.IsAdditionally == false)
                               .Select(a => a.Id)
                               .ToArray();

            var rowValues = model.RowValues.Where(a => tempRowIds.Contains(a.RowId));

            ws.Row(contentRowIndex).Cell(4).Value = rowValues.Sum(a => a.C1);
            ws.Row(contentRowIndex).Cell(5).Value = rowValues.Sum(a => a.C2);
            ws.Row(contentRowIndex).Cell(6).Value = rowValues.Sum(a => a.C3);
            ws.Row(contentRowIndex).Cell(7).Value = rowValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(8).Value = rowValues.Sum(a => a.C5);
            ws.Row(contentRowIndex).Cell(9).Value = rowValues.Sum(a => a.C6);
            ws.Row(contentRowIndex).Cell(10).Value = rowValues.Sum(a => a.C7);
            ws.Row(contentRowIndex).Cell(11).Value = rowValues.Sum(a => a.C8);
            ws.Row(contentRowIndex).Cell(12).Value = rowValues.Sum(a => a.C9);
            ws.Row(contentRowIndex).Cell(13).Value = rowValues.Sum(a => a.C10);
            ws.Row(contentRowIndex).Cell(14).Value = rowValues.Sum(a => a.C11);
            ws.Row(contentRowIndex).Cell(15).Value = rowValues.Sum(a => a.C12);
            contentRowIndex++;

            foreach (var row in rows)
            {
                if (row.IsAdditionally == true)
                {
                    var rowValue = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                    if (row.IsBold)
                        ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
                    ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                    ws.Row(contentRowIndex).Cell(2).Value = row.Name;
                    ws.Row(contentRowIndex).Cell(3).Value = row.Code;
                    setValues(ws.Row(contentRowIndex), rowValue);
                    if (rowValue == null)
                    {
                        ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                    }
                    contentRowIndex++;
                    foreach (var childRow in rows.Where(a => a.ParentId == row.Id))
                    {
                        var childRowValue = model.RowValues.FirstOrDefault(a => a.RowId == childRow.Id);
                        if (childRow.IsBold)
                            ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
                        ws.Row(contentRowIndex).Cell(1).Value = childRow.Number;
                        ws.Row(contentRowIndex).Cell(2).Value = "      " + childRow.Name;
                        ws.Row(contentRowIndex).Cell(3).Value = childRow.Code;
                        setValues(ws.Row(contentRowIndex), childRowValue);
                        if (childRowValue == null)
                        {
                            ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                        }
                        contentRowIndex++;
                    }
                }
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

