                    setSummaryValues(ws.Row(contentRowIndex), rowValue);
                    if (rowValue == null)
                    {
                        ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                    }
                    contentRowIndex++;
                    foreach (var childRow in rows.Where(a => a.ParentId == row.Id))
                    {
                        var childRowValue = model.Report[model.OrganizationId].Values.FirstOrDefault(a => a.RowId == childRow.Id);
                        if (childRow.IsBold)
                            ws.Row(contentRowIndex).Cells(1, 15).Style.Font.Bold = true;
                        ws.Row(contentRowIndex).Cell(1).Value = childRow.Number;
                        ws.Row(contentRowIndex).Cell(2).Value = "      " + childRow.Name;
                        ws.Row(contentRowIndex).Cell(3).Value = childRow.Code;
                        setSummaryValues(ws.Row(contentRowIndex), childRowValue);
                        if (childRowValue == null)
                        {
                            ws.Range(contentRowIndex, 4, contentRowIndex, 15).Merge();
                        }
                        contentRowIndex++;
                    }
                }
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

