            var planRowValues = model.Plan[model.OrganizationId].Values.Where(a => tempRowIds.Contains(a.RowId));

            ws.Row(contentRowIndex).Cell(5).Value = planRowValues.Sum(a => a.C2);
            ws.Row(contentRowIndex).Cell(7).Value = rowValues.Sum(a => a.C2);
            ws.Row(contentRowIndex).Cell(9).Value = planRowValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(11).Value = rowValues.Sum(a => a.C4);
            ws.Row(contentRowIndex).Cell(13).Value = planRowValues.Sum(a => a.C6);
            ws.Row(contentRowIndex).Cell(15).Value = rowValues.Sum(a => a.C6);
            ws.Row(contentRowIndex).Cell(17).Value = planRowValues.Sum(a => a.C8);
            ws.Row(contentRowIndex).Cell(19).Value = rowValues.Sum(a => a.C8);
            ws.Row(contentRowIndex).Cell(21).Value = planRowValues.Sum(a => a.C10);
            ws.Row(contentRowIndex).Cell(23).Value = rowValues.Sum(a => a.C10);

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

        private static void setSummaryValues(IXLRow contentRow, Report317SummaryResultModel rowValue, bool isMergeable, Report317SummaryPlanResultModel planValue)
        {
            contentRow.Cells(1, 23).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            contentRow.Cells(1, 23).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            contentRow.Cells(3, 23).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            contentRow.Cell(2).Style.Alignment.WrapText = true;
            if (rowValue != null)
            {
                contentRow.Cell(6).Value = rowValue.C1;
                contentRow.Cell(10).Value = rowValue.C3;
                contentRow.Cell(14).Value = rowValue.C5;
                contentRow.Cell(18).Value = rowValue.C7;
                contentRow.Cell(22).Value = rowValue.C9;
                if (!isMergeable)
                {
                    contentRow.Cell(7).Value = rowValue.C2;
                    contentRow.Cell(11).Value = rowValue.C4;
                    contentRow.Cell(15).Value = rowValue.C6;
                    contentRow.Cell(19).Value = rowValue.C8;
                    contentRow.Cell(23).Value = rowValue.C10;
                }
            }
            if (planValue != null)
            {
                contentRow.Cell(4).Value = planValue.C1;
                contentRow.Cell(8).Value = planValue.C3;
                contentRow.Cell(12).Value = planValue.C5;
                contentRow.Cell(16).Value = planValue.C7;
                contentRow.Cell(20).Value = planValue.C9;
                if (!isMergeable)
                {
                    contentRow.Cell(5).Value = planValue.C2;
                    contentRow.Cell(9).Value = planValue.C4;
                    contentRow.Cell(13).Value = planValue.C6;
                    contentRow.Cell(17).Value = planValue.C8;
                    contentRow.Cell(21).Value = planValue.C10;
                }
            }
        }
