        #region Report 323
        public static MemoryStream AsExcelStream(this Report323RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report323Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("Ведомость двежения фонда в дорогах и сооружениях за {0} год по автодорогам местного значения по {1}", model.Year, model.OrganizationName);

            #endregion

            #region Content

            var contentRowIndex = 8;

            var rows = IoCHelper.GetInstance<Report323RowService>().GetAsRenderModel().OrderBy(a => a.Order).ToArray();

            foreach (var row in rows)
            {
                var rowValue = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                if (row.MergeableParentId == null && row.ParentId == null)
                {
                    foreach (var childRow in rows.Where(a => a.ParentId == row.Id))
                    {
                        var childRowValue = model.RowValues.FirstOrDefault(a => a.RowId == childRow.Id);
                        if (childRow.MergeableParentId == null)
                        {
                            foreach (var grandChildRow in rows.Where(a => a.ParentId == childRow.Id))
                            {
                                var grandChildRowValue = model.RowValues.FirstOrDefault(a => a.RowId == grandChildRow.Id);
                                if (grandChildRow.MergeableParentId == null)
                                {
                                    if (grandChildRow.IsBold)
                                        ws.Row(contentRowIndex).Cells(1, 28).Style.Font.Bold = true;
                                    ws.Row(contentRowIndex).Cell(1).Value = grandChildRow.Number;
                                    ws.Row(contentRowIndex).Cell(2).Value = grandChildRow.Name.Replace("{{year}}", model.Year.AsString());
                                    setValues(ws.Row(contentRowIndex), grandChildRowValue);
                                    contentRowIndex++;
                                }
                            }
                            if (childRow.IsBold)
                                ws.Row(contentRowIndex).Cells(1, 28).Style.Font.Bold = true;
                            ws.Row(contentRowIndex).Cell(1).Value = childRow.Number;
                            ws.Row(contentRowIndex).Cell(2).Value = childRow.Name.Replace("{{year}}", model.Year.AsString());
                            setValues(ws.Row(contentRowIndex), childRowValue);
                            contentRowIndex++;
                        }
                    }
                    if (row.IsBold)
                        ws.Row(contentRowIndex).Cells(1, 28).Style.Font.Bold = true;
                    ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                    ws.Row(contentRowIndex).Cell(2).Value = row.Name.Replace("{{year}}", model.Year.AsString());
                    setValues(ws.Row(contentRowIndex), rowValue);
                    contentRowIndex++;
                }
            }

            #endregion

            wb.Save();
            memoryStream.Seek(0, SeekOrigin.Begin);

            return memoryStream;
        }

