        #region Report 400
        public static MemoryStream AsExcelStream(this Report400RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report400Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} томонидан {1} йилда умумий фойдаланишдаги халқаро, давлат ва махаллий аҳамиятдаги автомобиль йўлларини,шахар кўчалари, намунавий уй-жой, ички хўжалик йўлларини қуриш, қайта қуриш ва таъмирлаш объектларига талаб қилинадиган қурилиш материаллари тўғрисида маълумот", model.OrganizationName, model.Year);
            ws.Row(4).Cell(3).Value = string.Format("{0} йилда ишга туширилиши кўзда тутилган қувват", model.Year);
            ws.Row(4).Cell(5).Value = string.Format("{0} йилга жами талаб этиладиган асосий қурилиш материаллари", model.Year);
            ws.Row(4).Cell(16).Value = string.Format("Мавжуд захира миқдори (жорий йилнинг 01.12.{0}й ҳолатига)", model.Year);
            ws.Row(4).Cell(27).Value = string.Format("{0} йилга Қўшимча талаб этиладиган миқдор", model.Year);

            #endregion

            #region Content

            var contentRowIndex = 7;

            var rows = IoCHelper.GetInstance<Report400RowService>().GetAsRenderModel().OrderBy(a => a.Order).ToArray();

            var total = new Report400RowValueViewModel
            {
                ObjectName = model.OrganizationName,
                C1 = 0,
                C2 = 0,
                C3 = 0,
                C4 = 0,
                C5 = 0,
                C6 = 0,
                C7 = 0,
                C8 = 0,
                C9 = 0,
                C10 = 0,
                C11 = 0,
                C12 = 0,
                C13 = 0,
                C14 = 0,
                C15 = 0,
                C16 = 0,
                C17 = 0,
                C18 = 0,
                C19 = 0,
                C20 = 0,
                C21 = 0,
                C22 = 0,
                C23 = 0,
                C24 = 0,
                C25 = 0,
                C26 = 0,
                C27 = 0,
                C28 = 0,
                C29 = 0,
                C30 = 0,
                C31 = 0,
                C32 = 0,
                C33 = 0,
                C34 = 0,
                C35 = 0,
            };

            foreach (var row in rows.Where(a => a.ParentId == null))
            {
                var rowValue = model.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                setValues(ws, contentRowIndex, rowValue, row, model.Year.ToString());
                contentRowIndex++;
                total.C1 += rowValue.C1;
                total.C2 += rowValue.C2;
                total.C3 += rowValue.C3;
                total.C4 += rowValue.C4;
                total.C5 += rowValue.C5;
                total.C6 += rowValue.C6;
                total.C7 += rowValue.C7;
                total.C8 += rowValue.C8;
                total.C9 += rowValue.C9;
                total.C10 += rowValue.C10;
                total.C11 += rowValue.C11;
                total.C12 += rowValue.C12;
                total.C13 += rowValue.C13;
                total.C14 += rowValue.C14;
                total.C15 += rowValue.C15;
                total.C16 += rowValue.C16;
                total.C17 += rowValue.C17;
                total.C18 += rowValue.C18;
                total.C19 += rowValue.C19;
                total.C20 += rowValue.C20;
                total.C21 += rowValue.C21;
                total.C22 += rowValue.C22;
                total.C23 += rowValue.C23;
                total.C24 += rowValue.C24;
                total.C25 += rowValue.C25;
                total.C26 += rowValue.C26;
                total.C27 += rowValue.C27;
                total.C28 += rowValue.C28;
                total.C29 += rowValue.C29;
