                total.C34 += rowValue.C34;
                total.C35 += rowValue.C35;

                foreach (var item in model.RowValues.Where(a => a.ParentRowId == row.Id))
                {
                    setValues(ws, contentRowIndex, item, null, model.Year.ToString());
                    contentRowIndex++;
                }
                foreach (var childRow in rows.Where(a => a.ParentId == row.Id))
                {
                    var childRowValue = model.RowValues.FirstOrDefault(a => a.RowId == childRow.Id);
                    setValues(ws, contentRowIndex, childRowValue, childRow, model.Year.ToString());
                    contentRowIndex++;
                    foreach (var item1 in model.RowValues.Where(a => a.ParentRowId == childRow.Id))
                    {
                        setValues(ws, contentRowIndex, item1, null, model.Year.ToString());
                        contentRowIndex++;
                    }
                    foreach (var grantChildRow in rows.Where(a => a.ParentId == childRow.Id))
                    {
                        var grantChildRowValue = model.RowValues.FirstOrDefault(a => a.RowId == grantChildRow.Id);
                        setValues(ws, contentRowIndex, grantChildRowValue, grantChildRow, model.Year.ToString());
                        contentRowIndex++;
                        foreach (var item2 in model.RowValues.Where(a => a.ParentRowId == grantChildRow.Id))
                        {
                            setValues(ws, contentRowIndex, item2, null, model.Year.ToString());
                            contentRowIndex++;
