                ws.Row(6).Cells(1, 38).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(6).Cells(1, 38).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(6).Cells(3, 38).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                ws.Row(6).Cells(1, 38).Style.Alignment.WrapText = true;
                ws.Row(6).Cells(1, 38).Style.Font.Bold = true;
                ws.Row(6).Cell(2).Value = total.ObjectName;
