        private static void setValues(IXLWorksheet ws, int contentRowIndex, Report400RowValueViewModel rowValue, Report400RowModel row, string year)
        {
            ws.Row(contentRowIndex).Cells(1, 38).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 38).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(3, 38).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 38).Style.Alignment.WrapText = true;
            if (row != null)
            {
                if (row.IsBold)
                    ws.Row(contentRowIndex).Cells(1, 38).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                ws.Row(contentRowIndex).Cell(2).Value = row.Name.Replace("{{year}}", year);
            }
            else if (rowValue != null)
            {
                ws.Row(contentRowIndex).Cell(2).Value = rowValue.ObjectName;
            }
            if (rowValue != null)
            {
                ws.Row(contentRowIndex).Cell(3).Value = rowValue.C1;
                ws.Row(contentRowIndex).Cell(4).Value = rowValue.C2;
                ws.Row(contentRowIndex).Cell(5).Value = rowValue.C3;
                ws.Row(contentRowIndex).Cell(6).Value = rowValue.C4;
                ws.Row(contentRowIndex).Cell(7).Value = rowValue.C5;
                ws.Row(contentRowIndex).Cell(8).Value = rowValue.C6;
                ws.Row(contentRowIndex).Cell(9).Value = rowValue.C7;
