        #region Report 401
        public static MemoryStream AsExcelStream(this Report401RecordViewModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report401Record.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} йил {1} ойи бўйича маҳаллий битум маҳсулотини ишлаб чиқарувчилар томонидан истеъмолчиларга етказиб бериш тўғрисида маълумот", model.Year, model.Month.AsEnumMember().Description);

            #endregion

            var rowIndex = 7;
            var plan = IoCHelper.GetInstance<Report401PlanService>().AllAsQueryable.FirstOrDefault(a => a.OrganizationId == model.OrganizationId && a.Year == model.Year && a.Month == model.Month);

            IXLRow contentRowFirst = ws.Row(rowIndex);
            contentRowFirst.Cells(1, 12).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            contentRowFirst.Cells(1, 16).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            contentRowFirst.Cell(2).Value = model.OrganizationName;
            contentRowFirst.Cell(4).Value = model.C5;
            contentRowFirst.Cell(6).Value = model.C1;
            contentRowFirst.Cell(8).Value = model.C2;
            contentRowFirst.Cell(10).Value = model.C3;
            contentRowFirst.Cell(12).Value = model.C4;
