        private static void setSummaryValues(IXLWorksheet ws, int contentRowIndex, Report401SummaryResultMergedModel rowValue, bool IsBold)
        {
            ws.Row(contentRowIndex).Cells(1, 12).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 12).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(3, 12).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 12).Style.Alignment.WrapText = true;
            if (IsBold)
                ws.Row(contentRowIndex).Cells(1, 12).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cell(2).Value = rowValue.OrganizationName;
            if (rowValue.Record != null)
            {
                ws.Row(contentRowIndex).Cell(4).Value = rowValue.Record.C5;
                ws.Row(contentRowIndex).Cell(6).Value = rowValue.Record.C1;
                ws.Row(contentRowIndex).Cell(8).Value = rowValue.Record.C2;
                ws.Row(contentRowIndex).Cell(10).Value = rowValue.Record.C3;
                ws.Row(contentRowIndex).Cell(12).Value = rowValue.Record.C4;
            }
            if (rowValue.Plan != null)
            {
                ws.Row(contentRowIndex).Cell(3).Value = rowValue.Plan.C5;
                ws.Row(contentRowIndex).Cell(5).Value = rowValue.Plan.C1;
                ws.Row(contentRowIndex).Cell(7).Value = rowValue.Plan.C2;
                ws.Row(contentRowIndex).Cell(9).Value = rowValue.Plan.C3;
                ws.Row(contentRowIndex).Cell(11).Value = rowValue.Plan.C4;
            }
        }


