        private static void setValues(IXLWorksheet ws, int contentRowIndex, Report402RowValueViewModel rowValue, Report402RowModel row, bool IsParentRow)
        {
            ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(3, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.WrapText = true;
            if (row != null)
            {
                if (row.IsBold)
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cell(1).Value = row.Number;
                if (IsParentRow)
                    ws.Row(contentRowIndex).Cell(2).Value = row.Name;
