        public static MemoryStream AsExcelStream(this Report402SummaryRenderModel model)
        {
            string filePath = Path.Combine(HttpContext.Current.Server.MapPath("~/App_Data/ExcelTemplates/"), CultureHelper.CurrentCultureName, "Report402Summary.xlsx");
            byte[] data = File.ReadAllBytes(filePath);

            MemoryStream memoryStream = new MemoryStream();
            memoryStream.Write(data, 0, data.Length);

            MarkupCompatibilityProcessSettings processSettings = new MarkupCompatibilityProcessSettings
                (
                MarkupCompatibilityProcessMode.ProcessAllParts,
                FileFormatVersions.Office2007
                );
            OpenSettings openSettings = new OpenSettings()
            {
                MarkupCompatibilityProcessSettings = processSettings,
                AutoSave = true
            };

            var organizationName = IoCHelper.GetInstance<OrganizationService>().ByID(model.OrganizationId).GetCurrentLocale().ShortName;

            XLWorkbook wb = new XLWorkbook(memoryStream);
            IXLWorksheet ws = wb.Worksheet("Sheet1");

            #region Title

            IXLRow titleRow = ws.Row(2);
            titleRow.Cell(1).Value = string.Format("{0} тизимидаги корхоналар томонидан {1} йилда умумий фойдаланишдаги автомобиль йўлларини қуриш, реконструкция қилиш ва тўла таъмирлаш ишлари бўйича амалга оширилган ишлар тўғрисида маълумот", organizationName, model.Year);

            #endregion

            #region Header

            ws.Row(4).Cell(8).Value = string.Format("Объектнинг қолдиқ қиймати {0}.01.01. ҳолатига", model.Year);
            ws.Row(5).Cell(9).Value = string.Format("01.01.{0} й ҳолатига", model.Year);
            ws.Row(5).Cell(11).Value = string.Format("{0} да молиялаштирилган", model.Year);
            ws.Row(4).Cell(12).Value = string.Format("{0} йил лимити", model.Year);
            ws.Row(4).Cell(16).Value = string.Format("{0}-{1}", Month.January.AsEnumMember().Description, model.Month.AsEnumMember().Description);
            ws.Row(4).Cell(89).Value = string.Format("1.01.{0} холатига бажарилган", model.Year);
            ws.Row(4).Cell(90).Value = string.Format("1.01.{0} холатига молиялаштирилган", model.Year);
            ws.Row(4).Cell(93).Value = string.Format("Сальдо на 1.01.{0}г", model.Year);

            #endregion

            wb.Worksheet(1).CopyTo(wb, "Модернизация");
            wb.Worksheet(1).CopyTo(wb, "УНА");
            wb.Worksheet(1).CopyTo(wb, "Депозит");
            wb.Worksheet(1).CopyTo(wb, "ПП-2458");
            wb.Worksheet(1).CopyTo(wb, "ПП-2313");
            wb.Worksheet(1).CopyTo(wb, "ПП-2458 + ПП-2313");
            wb.Worksheet(1).CopyTo(wb, "ПП-2458 + все");
            wb.Worksheet(1).CopyTo(wb, "ПП-2458 Узавтойул");
            wb.Worksheet(1).CopyTo(wb, "ПКМ-126");
            wb.Worksheet(1).CopyTo(wb, "ПКМ-126 Узавтойул");
            wb.Worksheet(1).CopyTo(wb, "Инвестиция");
            wb.Worksheet(1).CopyTo(wb, "ЯБХИК шах");
            wb.Worksheet(1).CopyTo(wb, "ЯБХИК мах йул");
            wb.Worksheet(1).CopyTo(wb, "Рокад");
            wb.Worksheet(1).CopyTo(wb, "ДФ общий");
            wb.Worksheet(1).CopyTo(wb, "ДФ об уз");
            wb.Worksheet(1).CopyTo(wb, "Свод");
            foreach (var region in model.Report)
            {
                wb.Worksheet(1).CopyTo(wb, region.Organization.RegionName);
            }
            wb.Worksheet(1).Delete();

            #region totalModel
            var total = new Report402RowValueViewModel();
            initializeModel(total);
            total.ObjectName = "Республика бўйича жами";

            var uzavtoyulTotal = new Report402RowValueViewModel();
            initializeModel(uzavtoyulTotal);
            uzavtoyulTotal.ObjectName = "\"Узавтойўл\" АК";

            var regionTotal = new Report402RowValueViewModel();
            initializeModel(regionTotal);

            var uzavtoyulRegionTotal = new Report402RowValueViewModel();
            initializeModel(uzavtoyulRegionTotal);
            uzavtoyulRegionTotal.ObjectName = "\"Узавтойўл\" АК";

            var reconstructionTotal = new Report402RowValueViewModel();
            initializeModel(reconstructionTotal);
            reconstructionTotal.ObjectName = "Реконструкция объектлар";

            var regionReconstructionTotal = new Report402RowValueViewModel();
            initializeModel(regionReconstructionTotal);
            regionReconstructionTotal.ObjectName = "Реконструкция";
            #endregion

            var rows = IoCHelper.GetInstance<Report402RowService>().GetAsRenderModel().OrderBy(a => a.Order).ToArray();
            var contentRowIndex = 9;
            var enableReconstruction = false;
            var wsIndex = 1;

            #region Модернизация

            ws = wb.Worksheet(wsIndex);
            wsIndex++;

            foreach (var item in model.Report)
            {
                foreach (var item1 in item.RowValues)
                {
                    if (item1.IsModernization && item1.RepairType == RoadRepairType.Reconstruction)
                    {
                        enableReconstruction = true;
                    }
                }
            }
            contentRowIndex = enableReconstruction ? 10 : 9;

            ws.Range(contentRowIndex, 2, contentRowIndex, 100).Merge();
            ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(3, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
            ws.Row(contentRowIndex).Cell(2).Value = "шу жумладан";
            contentRowIndex++;

            ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
            ws.Row(contentRowIndex).Cells(1, 100).Style.Font.Bold = true;
            ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.WrapText = true;
            ws.Row(contentRowIndex).Cell(2).Value = "\"Узавтойўл\" АК";
            var uzavtoyulTotalRowIndex = contentRowIndex;
            contentRowIndex++;

            foreach (var report in model.Report)
            {
                ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Fill.BackgroundColor = XLColor.FromHtml("#B8CCE4");
                ws.Row(contentRowIndex).Cell(2).Value = report.Organization.RegionName;
                var regionTotalRowIndex = contentRowIndex;
                contentRowIndex++;

                var regionReconstructionTotalRowIndex = contentRowIndex;
                if (enableReconstruction)
                {
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.WrapText = true;
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Font.Bold = true;
                    ws.Row(contentRowIndex).Cells(1, 100).Style.Fill.BackgroundColor = XLColor.FromHtml("#B8CCE4");
                    ws.Row(contentRowIndex).Cell(2).Value = "Реконструкция";
                    contentRowIndex++;
                }

                ws.Row(contentRowIndex).Cells(1, 100).Style.Border.SetOutsideBorder(XLBorderStyleValues.Thin);
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Fill.BackgroundColor = XLColor.FromHtml("#FCD5B4");
                ws.Row(contentRowIndex).Cells(1, 100).Style.Font.Bold = true;
                ws.Row(contentRowIndex).Cells(1, 100).Style.Alignment.WrapText = true;
                ws.Row(contentRowIndex).Cell(2).Value = "\"Узавтойўл\" АК";
                var uzavtoyulRegionTotalRowIndex = contentRowIndex;
                contentRowIndex++;

                foreach (var row in report.RowValues.Where(a => a.IsModernization && a.ConstructionCompany == RoadConstructionCompany.RJY))
                {
                    setSummaryValues(ws, contentRowIndex, row, null);
                    contentRowIndex++;
                    sumValues(total, row);
                    sumValues(regionTotal, row);
                    if (row.RegionOrganizationId.HasValue)
                    {
                        sumValues(uzavtoyulTotal, row);
                        sumValues(uzavtoyulRegionTotal, row);
                    }
                    if (row.RepairType == RoadRepairType.Reconstruction)
                    {
                        sumValues(reconstructionTotal, row);
                        sumValues(regionReconstructionTotal, row);
                    }
                }
                ws.Row(regionTotalRowIndex).Cells(1, 100).Style.Font.Bold = true;
                regionTotal.ObjectName = report.Organization.RegionName;
                setSummaryValues(ws, regionTotalRowIndex, regionTotal, null);

                if (enableReconstruction)
                {
                    ws.Row(regionReconstructionTotalRowIndex).Cells(1, 100).Style.Font.Bold = true;
                    setSummaryValues(ws, regionReconstructionTotalRowIndex, regionReconstructionTotal, null);
                }

                ws.Row(uzavtoyulRegionTotalRowIndex).Cells(1, 100).Style.Font.Bold = true;
                setSummaryValues(ws, uzavtoyulRegionTotalRowIndex, uzavtoyulRegionTotal, null);

                initializeModel(regionTotal);
                initializeModel(regionReconstructionTotal);
                initializeModel(uzavtoyulRegionTotal);
            }
            ws.Row(8).Cells(1, 100).Style.Font.Bold = true;
            setSummaryValues(ws, 8, total, null);

            if (enableReconstruction)
            {
                ws.Row(9).Cells(1, 100).Style.Font.Bold = true;
                setSummaryValues(ws, 9, reconstructionTotal, null);
            }

            ws.Row(uzavtoyulTotalRowIndex).Cells(1, 100).Style.Font.Bold = true;
            setSummaryValues(ws, uzavtoyulTotalRowIndex, uzavtoyulTotal, null);

            initializeModel(total);
            initializeModel(reconstructionTotal);
            initializeModel(uzavtoyulTotal);
            #endregion

            #region УНА
            ws = wb.Worksheet(wsIndex);
            wsIndex++;

            enableReconstruction = false;

