                var parentTotal = new Report402RowValueViewModel();
                initializeModel(parentTotal);

                var rowTotal = new Report402RowValueViewModel();
                initializeModel(rowTotal);

                foreach (var row in rows.Where(a => a.ParentId == null))
                {
                    var rowValue = region.RowValues.FirstOrDefault(a => a.RowId == row.Id);
                    if (rowValue != null && !rowValue.IsExceptional) sumValues(total, rowValue);
                    sumValues(parentTotal, rowValue);
                    parentTotal.ObjectName = row.Name;
                    var parentTotalRowIndex = contentRowIndex++;
                    foreach (var item in region.RowValues.Where(a => a.ParentRowId == row.Id))
                    {
                        setValues(ws, contentRowIndex, item, null, false);
                        sumValues(parentTotal, item);
                        if (item != null && !item.IsExceptional) sumValues(total, item);
